def env_value(name, default):
    value = os.environ.get(name)
    if value in (None, ""):
        return default
    return value


def env_bool(name, default=False):
    value = os.environ.get(name)
    if value in (None, ""):
        return bool(default)
    return str(value).strip().lower() in {"1", "true", "yes", "on", "enabled"}


