HTML = HTML.replace("__INKDROP_UI_CSS_VERSION__", INKDROP_UI_CSS_VERSION)
HTML = HTML.replace("__INKDROP_UI_JS_VERSION__", INKDROP_UI_JS_VERSION)


def command_env(extra=None):
    env = os.environ.copy()
    if extra:
        env.update({str(key): str(value) for key, value in dict(extra).items() if value is not None})
    return env


def manual_source_import_child_env(item=None, source_path=None):
    # Keep preview and live children on one bounded contract. Completed-import
    # previews do not write status or poll library visibility, so both controls
    # are inert for dry runs while protecting future child-path changes.
    env = {"INKDROP_COMPLETED_IMPORT_STATUS_SYNC_MODE": "defer"}
    marker = inkdrop_completed_import._auto_inspect_marker(item or {})
    if marker and source_path is not None:
        source_path_hash = hashlib.sha256(
            str(Path(source_path).resolve()).replace("\\", "/").casefold().encode("utf-8", errors="replace")
        ).hexdigest()
        env["INKDROP_AUTO_INSPECT_CONTEXT_JSON"] = json.dumps(
            {"auto_inspect": marker, "source_path_hash": source_path_hash},
            sort_keys=True,
            separators=(",", ":"),
        )
    return env


def run_command(args, timeout=75, env=None):
    popen_kwargs = {
        "stdout": subprocess.PIPE,
        "stderr": subprocess.PIPE,
        "text": True,
        "env": command_env(env) if env else None,
    }
    if hasattr(os, "setsid"):
        popen_kwargs["preexec_fn"] = os.setsid
    else:
        popen_kwargs["creationflags"] = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
    proc = inkdrop_process_lifecycle.popen_tracked(args, **popen_kwargs)
    try:
        output, error = inkdrop_process_lifecycle.communicate_tracked(proc, timeout=timeout)
    except subprocess.TimeoutExpired as exc:
        if hasattr(os, "killpg") and hasattr(os, "getpgid"):
            try:
                os.killpg(os.getpgid(proc.pid), signal.SIGTERM)
            except Exception:
                proc.kill()
        else:
            proc.kill()
        try:
            output, error = inkdrop_process_lifecycle.communicate_tracked(proc, timeout=5)
        except subprocess.TimeoutExpired:
            if hasattr(os, "killpg") and hasattr(os, "getpgid"):
                try:
                    os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
                except Exception:
                    proc.kill()
            else:
                proc.kill()
            output, error = inkdrop_process_lifecycle.communicate_tracked(proc)
        exc.output = output
        exc.stderr = error
        raise
    output = (output or "").strip()
    error = (error or "").strip()
    if proc.returncode != 0:
        raise RuntimeError(error or output or f"command failed: {proc.returncode}")
    return output


def with_import_lock(args, wait_seconds=60):
    return [
        "/usr/bin/flock",
        "-E",
        str(IMPORT_LOCK_BUSY_CODE),
        "-w",
        str(max(1, int(wait_seconds or 1))),
        str(IMPORT_LOCK),
        *args,
    ]


def import_lock_busy_result():
    return {
        "manual_source_import_busy": True,
        "state": "import_busy",
        "count": 0,
        "imported": [],
        "verification": {
            "checked_count": 0,
            "failure_count": 0,
            "failures": [],
        },
        "note": "Another import worker is already running; this row will retry on the next automation pass.",
    }


def manual_source_import_timeout_result(timeout_seconds):
    return {
        "manual_source_import_timeout": True,
        "state": "import_timeout",
        "count": 0,
        "imported": [],
        "verification": {
            "checked_count": 0,
            "failure_count": 1,
            "failures": [
                {
                    "reason": "manual_source_import_timeout",
                    "timeout_seconds": int(timeout_seconds or 0),
                }
            ],
        },
        "note": f"Import exceeded {int(timeout_seconds or 0)} seconds; InkDrop will retry with the next eligible candidate.",
    }


def is_import_lock_busy_error(exc):
    text = str(exc or "")
    return (
        f"command failed: {IMPORT_LOCK_BUSY_CODE}" in text
        or f"exit status {IMPORT_LOCK_BUSY_CODE}" in text
        or f"returned non-zero exit status {IMPORT_LOCK_BUSY_CODE}" in text
    )


def read_json_body(handler, max_bytes=8192):
    length = int(handler.headers.get("Content-Length") or "0")
    if length <= 0 or length > int(max_bytes or 8192):
        return {}
    return json.loads(handler.rfile.read(length).decode("utf-8"))


def read_strict_json_body(handler, max_bytes):
    length = int(handler.headers.get("Content-Length") or "0")
    if length <= 0 or length > int(max_bytes):
        raise ValueError("request JSON body has an invalid size")
    return inkdrop_backup_restore.parse_strict_json_object(
        handler.rfile.read(length),
        max_bytes=max_bytes,
        label="request JSON body",
    )


def download_client_expected_revision(headers, payload=None):
    raw = str((headers or {}).get("If-Match") or "").strip()
    if raw:
        raw = raw.removeprefix("W/").strip().strip('"')
    elif isinstance(payload, dict):
        raw = str(payload.get("revision") or payload.get("expected_revision") or "").strip()
    try:
        revision = int(raw)
    except (TypeError, ValueError):
        raise ValueError("If-Match or expected_revision is required") from None
    if revision < 1:
        raise ValueError("revision must be positive")
    return revision


def download_client_error_status(exc):
    text = str(exc or "").lower()
    if isinstance(exc, LookupError) or "not found" in text:
        return 404
    if any(token in text for token in ("revision conflict", "must be unique", "already uses", "still referenced", "active download tasks")):
        return 409
    return 400


def download_client_instance_path(path):
    prefix = "/api/download-clients/"
    suffix = str(path or "").removeprefix(prefix).strip("/") if str(path or "").startswith(prefix) else ""
    return unquote(suffix) if suffix and "/" not in suffix else ""


# Reachable regardless of setup state: the setup/login UI shell, its art,
# and the status route that shell needs to decide what to render. None of
# these carry operational data.
INKDROP_AUTH_SETUP_SAFE_PATHS = {
    "/",
    "/inkdrop-logo-mark.png",
    "/static/img/inkdrop-auth-backdrop.webp",
    "/api/inkdrop-auth/status",
    "/api/auth/status",
    # /status.json is this container's liveness endpoint, not just a UI feed.
    # inkdrop_container_healthcheck.py probes it and fails on any non-2xx, and
    # that healthcheck is wired into the Dockerfile and both compose services,
    # so gating it made a fresh install report unhealthy forever and
    # `docker compose up --wait` never return. The release workflow curls it
    # against a never-set-up container too. It stays reachable; what it says
    # before setup is what changes -- see setup_required_status_payload().
    "/status.json",
}
# Reachable once setup is no longer required. /status.json and
# /api/system/version carry real operational data (host paths, counts) --
# see SEC-03 -- and login/recovery routes are meaningless before an
# administrator exists. Public once claimed, same as before this file split.
INKDROP_AUTH_PUBLIC_PATHS = INKDROP_AUTH_SETUP_SAFE_PATHS | {
    "/status.json",
    "/api/system/version",
    "/api/inkdrop-auth/login",
    "/api/auth/login",
    "/api/auth/recovery/reset",
    "/api/inkdrop-auth/recovery/reset",
}
INKDROP_AUTH_STATUS_CACHE = {"ts": 0.0, "status": None, "key": None}
INKDROP_AUTH_STATUS_CACHE_LOCK = threading.Lock()
INKDROP_AUTH_STATUS_CACHE_TTL_SECONDS = 15


def inkdrop_auth_required_status(db_path=INKDROP_STATE_DB, environ=None):
    now = time.time()
    env = dict(os.environ if environ is None else environ)
    # Watch the auth store, not the state database: state file times move on
    # every background write, which made this cache miss on almost every
    # request. Auth changes land in the store; settings changes go through
    # clear_inkdrop_auth_status_cache().
    auth_db = inkdrop_auth.auth_store_path(db_path)
    try:
        db_mtime = auth_db.stat().st_mtime
    except OSError:
        db_mtime = 0.0
    try:
        wal_mtime = Path(str(auth_db) + "-wal").stat().st_mtime
    except OSError:
        wal_mtime = 0.0
    cache_key = (
        str(Path(db_path)),
        db_mtime,
        wal_mtime,
        str(env.get("INKDROP_AUTH_REQUIRED") or ""),
        str(env.get("INKDROP_EXTERNAL_AUTH_ENABLED") or ""),
        str(env.get("INKDROP_EXTERNAL_AUTH_HEADER") or ""),
        str(env.get("INKDROP_EXTERNAL_AUTH_TRUSTED_PROXIES") or ""),
        str(env.get("INKDROP_AUTH_MODE") or ""),
        str(env.get("INKDROP_AUTH_ALLOW_DISABLED") or ""),
        str(env.get("INKDROP_TRUSTED_LAN_TESTING") or ""),
    )
    cached = INKDROP_AUTH_STATUS_CACHE.get("status")
    if (
        isinstance(cached, dict)
        and INKDROP_AUTH_STATUS_CACHE.get("key") == cache_key
        and now - float(INKDROP_AUTH_STATUS_CACHE.get("ts") or 0) < INKDROP_AUTH_STATUS_CACHE_TTL_SECONDS
    ):
        return cached, bool(cached.get("required"))
    if not INKDROP_AUTH_STATUS_CACHE_LOCK.acquire(blocking=False):
        if isinstance(cached, dict) and INKDROP_AUTH_STATUS_CACHE.get("key") == cache_key:
            return cached, bool(cached.get("required"))
        required = str(env.get("INKDROP_AUTH_REQUIRED") or "").strip().lower() in {"1", "true", "yes", "on", "enabled"}
        status = {"ok": True, "required": required, "cached": False, "provisional": True}
        return status, required
    try:
        status = inkdrop_state.auth_status(db_path, environ=environ)
        INKDROP_AUTH_STATUS_CACHE.update({"ts": now, "status": status, "key": cache_key})
    except Exception:
        if isinstance(cached, dict) and INKDROP_AUTH_STATUS_CACHE.get("key") == cache_key:
            stale = dict(cached)
            stale["stale"] = True
            return stale, bool(stale.get("required"))
        raise
    finally:
        INKDROP_AUTH_STATUS_CACHE_LOCK.release()
    return status, bool(status.get("required"))


def clear_inkdrop_auth_status_cache():
    inkdrop_auth.clear_config_cache()
    with INKDROP_AUTH_STATUS_CACHE_LOCK:
        INKDROP_AUTH_STATUS_CACHE.update({"ts": 0.0, "status": None, "key": None})


def inkdrop_auth_is_public_path(path, method="GET", auth_status=None):
    path = str(path or "")
    method = str(method or "GET").upper()
    # While setup is required, nothing has claimed this install yet, so only
    # the strict setup-safe set is public -- not the full post-setup list.
    # Without this, /status.json and /api/system/version served their full
    # operational payload (host library paths, counts) to anyone who could
    # reach the port before an administrator existed, because those paths
    # never triggered the setup_required check in the first place -- see
    # inkdrop_auth_public_without_status_lookup(), which runs before any
    # status is even computed.
    allowed_paths = (
        INKDROP_AUTH_SETUP_SAFE_PATHS
        if auth_status and auth_status.get("setup_required")
        else INKDROP_AUTH_PUBLIC_PATHS
    )
    if path in allowed_paths:
        return True
    if path.startswith("/static/"):
        return True
    if path in {"/api/inkdrop-auth/bootstrap", "/api/auth/bootstrap"} and method == "POST":
        status = auth_status or inkdrop_state.auth_status(INKDROP_STATE_DB)
        # bootstrap_required alone only says "the built-in user table is
        # empty" -- true forever for a trusted-proxy install, since it never
        # populates that table. Requiring setup_required too closes the
        # route the moment enforcement goes live through ANY path (built_in
        # admin created, or external auth becoming ready), instead of only
        # when mode has no built-in table at all. bootstrap_required stays
        # in the check so a fresh built_in_or_external install -- external
        # not configured yet, so setup_required is still true -- can still
        # mint its first admin the normal way.
        built_in_auth = status.get("built_in_auth") or {}
        return bool(built_in_auth.get("bootstrap_required")) and bool(status.get("setup_required"))
    return False


def inkdrop_auth_public_without_status_lookup(path, method="GET"):
    # This is the fast path ensure_authorized() takes before it knows
    # whether setup is required -- so it can only ever hand out the
    # setup-safe set. Anything only public once claimed (/status.json,
    # /api/system/version, login, recovery) has to go through the
    # status-aware check in inkdrop_auth_is_public_path() instead, which
    # is what actually decides based on setup_required. Behavior for those
    # paths is unchanged once setup is complete -- this only removes the
    # zero-cost bypass they used to get before it was.
    path = str(path or "")
    method = str(method or "GET").upper()
    if path in INKDROP_AUTH_SETUP_SAFE_PATHS:
        return True
    if path.startswith("/static/"):
        return True
    return False


def inkdrop_auth_cookie_token(headers):
    cookie_header = headers.get("Cookie") if headers else ""
    if not cookie_header:
        return ""
    try:
        cookie = SimpleCookie()
        cookie.load(cookie_header)
        morsel = cookie.get("inkdrop_session")
        return str(morsel.value or "").strip() if morsel else ""
    except Exception:
        return ""


def inkdrop_auth_csrf_cookie_token(headers):
    cookie_header = headers.get("Cookie") if headers else ""
    if not cookie_header:
        return ""
    try:
        cookie = SimpleCookie()
        cookie.load(cookie_header)
        morsel = cookie.get("inkdrop_csrf")
        return str(morsel.value or "").strip() if morsel else ""
    except Exception:
        return ""


def inkdrop_auth_bearer_token(headers):
    auth_header = str(headers.get("Authorization") or "").strip() if headers else ""
    if auth_header.lower().startswith("bearer "):
        return auth_header.split(None, 1)[1].strip()
    return ""


def inkdrop_auth_api_key(headers):
    if not headers:
        return ""
    for name in ("X-InkDrop-API-Key", "X-Api-Key"):
        value = str(headers.get(name) or "").strip()
        if value:
            return value
    return ""


def inkdrop_auth_principal(headers, db_path=INKDROP_STATE_DB, environ=None, *, remote_addr=None, mark_api_key_used=False):
    config = inkdrop_auth.resolve_config(db_path, environ=environ)
    external = inkdrop_auth.external_principal(headers, remote_addr, config)
    if external:
        inkdrop_auth.audit_external_auth(
            db_path,
            external,
            user_agent=str((headers or {}).get("User-Agent") or ""),
        )
        return external
    api_key = inkdrop_auth_api_key(headers)
    if api_key and config.get("api_keys_enabled"):
        verified = inkdrop_auth.verify_api_key(db_path, api_key, mark_used=mark_api_key_used)
        if verified:
            return {"method": "api_key", "id": verified.get("id"), **verified}
    bearer_token = inkdrop_auth_bearer_token(headers)
    cookie_token = inkdrop_auth_cookie_token(headers)
    token = bearer_token or cookie_token
    if token:
        csrf_header = str((headers or {}).get("X-InkDrop-CSRF") or "").strip()
        csrf_cookie = inkdrop_auth_csrf_cookie_token(headers)
        csrf_token = ""
        if bearer_token:
            csrf_token = csrf_header
        elif csrf_header and csrf_cookie and hmac.compare_digest(csrf_header, csrf_cookie):
            csrf_token = csrf_header
        verified = inkdrop_auth.verify_session(
            db_path,
            token,
            csrf_token=csrf_token,
            touch=mark_api_key_used,
        )
        if verified:
            return {
                "method": "session",
                "transport": "bearer" if bearer_token else "cookie",
                "id": (verified.get("user") or {}).get("id"),
                **verified,
            }
    return None


def inkdrop_auth_session_cookie(token, *, clear=False, secure=False):
    secure_text = "; Secure" if secure else ""
    if clear:
        return f"inkdrop_session=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax{secure_text}"
    return f"inkdrop_session={str(token or '')}; Path=/; HttpOnly; SameSite=Lax{secure_text}"


def inkdrop_auth_csrf_cookie(token, *, clear=False, secure=False):
    secure_text = "; Secure" if secure else ""
    if clear:
        return f"inkdrop_csrf=; Path=/; Max-Age=0; SameSite=Strict{secure_text}"
    return f"inkdrop_csrf={str(token or '')}; Path=/; SameSite=Strict{secure_text}"


def inkdrop_request_is_https(headers, remote_addr=None, environ=None, db_path=INKDROP_STATE_DB):
    env = dict(os.environ if environ is None else environ)
    configured = str(env.get("INKDROP_AUTH_COOKIE_SECURE") or "auto").strip().lower()
    if configured in {"1", "true", "yes", "on", "always"}:
        return True
    if configured in {"0", "false", "no", "off", "never"}:
        return False
    config = inkdrop_auth.resolve_config(db_path, environ=env)
    if inkdrop_auth.remote_is_trusted(remote_addr, (config.get("external") or {}).get("trusted_proxies")):
        return str((headers or {}).get("X-Forwarded-Proto") or "").strip().lower() == "https"
    return False


INKDROP_AUTH_ACTION_POLICIES = {
    ("POST", "/api/auth/maintenance/cleanup"): {"action": "auth_state_cleanup", "scope": "maintenance", "admin_only": False, "destructive": False, "high_impact": False},
    ("POST", "/api/inkdrop-auth/maintenance/cleanup"): {"action": "auth_state_cleanup", "scope": "maintenance", "admin_only": False, "destructive": False, "high_impact": False},
    ("POST", "/api/auth/api-keys"): {"action": "api_key_create", "scope": "admin", "admin_only": True, "destructive": False, "high_impact": True},
    ("POST", "/api/auth/api-keys/revoke"): {"action": "api_key_revoke", "scope": "admin", "admin_only": True, "destructive": True, "high_impact": True},
    ("POST", "/api/inkdrop-auth/api-keys/create"): {"action": "api_key_create", "scope": "admin", "admin_only": True, "destructive": False, "high_impact": True},
    ("POST", "/api/inkdrop-auth/api-keys/revoke"): {"action": "api_key_revoke", "scope": "admin", "admin_only": True, "destructive": True, "high_impact": True},
    ("POST", "/api/auth/sessions/revoke"): {"action": "session_revoke_all", "scope": "admin", "admin_only": True, "destructive": True, "high_impact": True},
    ("POST", "/api/auth/password"): {"action": "password_change", "scope": "admin", "admin_only": True, "destructive": False, "high_impact": True},
    ("POST", "/api/auth/recovery/reset"): {"action": "password_recovery", "scope": "admin", "admin_only": True, "destructive": True, "high_impact": True},
}


def inkdrop_auth_action_policy(path, method):
    path = str(path or "")
    method = str(method or "GET").upper()
    explicit = inkdrop_auth_contracts.mutation_route_policy(path, method)
    if explicit:
        return {
            "action": explicit["action"],
            "scope": explicit["scope"],
            "admin_only": explicit["admin_only"],
            "destructive": explicit["destructive"],
            "high_impact": explicit["high_impact"],
        }
    explicit = INKDROP_AUTH_ACTION_POLICIES.get((method, path))
    if explicit:
        return dict(explicit)
    if method == "GET":
        if path.startswith("/api/inkdrop-diagnostics/") or path == "/api/system/update-status":
            return {"action": "advanced_diagnostics", "scope": "admin", "admin_only": True, "destructive": False, "high_impact": False}
        return {"action": "read", "scope": "read", "admin_only": False, "destructive": False, "high_impact": False}
    if path.startswith("/api/auth/") or path.startswith("/api/inkdrop-auth/"):
        return {"action": "auth_administration", "scope": "admin", "admin_only": True, "destructive": False, "high_impact": True}
    if any(part in path for part in (
        "maintenance", "cleanup", "clear", "remove", "delete", "restore",
        "quarantine", "manual-review", "bad-match", "backup",
    )) or method == "DELETE":
        return {"action": "destructive_maintenance", "scope": "admin", "admin_only": True, "destructive": True, "high_impact": True}
    if path.startswith("/api/inkdrop-settings"):
        return {"action": "settings_update", "scope": "settings", "admin_only": False, "destructive": False, "high_impact": False}
    if any(part in path for part in ("search", "source", "missing", "queue", "import", "download", "manga")):
        return {"action": "acquisition", "scope": "acquisition", "admin_only": False, "destructive": False, "high_impact": False}
    return {"action": "write", "scope": "write", "admin_only": False, "destructive": False, "high_impact": False}


def inkdrop_auth_required_scope(path, method):
    policy = inkdrop_auth_action_policy(path, method)
    return policy["scope"], policy["admin_only"]


def read_json_file(path, default=None):
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def safe_query(value):
    value = str(value or "").strip()
    if not value or len(value) > 180:
        raise ValueError("query is required and must be under 180 characters")
    return value


def normalize_series_lookup_query(value):
    text = str(value or "").strip()
    if not text:
        raise ValueError("query is required and must be under 180 characters")
    text = re.sub(r"\s+", " ", text)
    text = text.replace(":", " ").replace("-", " ")
    text = text.replace(".", " ")
    text = text.replace("/", " ")
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        raise ValueError("query is required and must be under 180 characters")
    if len(text) > 180:
        text = text[:180].strip()
    return text


def series_lookup_query_variants(value):
    normalized = normalize_series_lookup_query(value)
    queries = []

    def add(candidate):
        if not candidate:
            return
        text = re.sub(r"\s+", " ", str(candidate).strip())
        if not text or len(text) > 180 or text in queries:
            return
        queries.append(text)

    add(normalized)
    add(str(value or "").strip())

    normalized_key = normalized.lower()
    words = normalized_key.split()
    if len(words) > 1:
        common_trailer = {"image", "comics", "comic", "manga", "mangas", "press", "media", "books", "entertainment", "publishing"}
        if words[-1] in common_trailer:
            add(" ".join(words[:-1]).title() if normalized else "")

        # strip known publisher suffixes from the normalized key
        all_hints = sorted(
            (COMICVINE_ENGLISH_PUBLISHER_HINTS | COMICVINE_NON_ENGLISH_PUBLISHER_HINTS),
            key=len,
            reverse=True,
        )
        for hint in all_hints:
            hint = str(hint or "").strip().lower()
            if not hint:
                continue
            if normalized_key == hint:
                break
            marker = f" {hint}"
            if normalized_key.endswith(marker):
                title = normalized_key[: -len(marker)].strip()
                add(title)
                break

        # fallback without the final two tokens for dot/space paste cases
        if len(words) >= 3 and words[-1] in common_trailer and len(words[-2]) > 2:
            add(" ".join(words[:-2]).title())

    return queries


def normalize_series_payload_name(value):
    value = str(value or "").strip()
    if not value:
        return ""
    if re.search(r"[./:]", value):
        normalized = normalize_series_lookup_query(value)
        return normalized if normalized else value
    return value


def safe_optional_text(value, limit=300):
    value = re.sub(r"\s+", " ", str(value or "").strip())
    if limit and len(value) > limit:
        return value[:limit].rstrip()
    return value


def safe_optional_filename(value, limit=1000):
    value = re.sub(r"[\x00-\x1f\x7f]+", " ", str(value or "").strip())
    if limit and len(value) > limit:
        return value[:limit].rstrip()
    return value


def filename_leaf(value, limit=260):
    parts = [part for part in re.split(r"[\\/]+", str(value or "")) if part]
    leaf = parts[-1] if parts else str(value or "")
    return safe_optional_filename(leaf, limit)


def safe_kind(value):
    value = str(value or "comics")
    if value not in {"comics", "ebooks"}:
        raise ValueError("invalid type")
    return value


def safe_prefer(value):
    value = str(value or "torrent")
    if value not in {"torrent", "usenet", "any"}:
        raise ValueError("invalid preference")
    return value


def safe_limit(value):
    return max(1, min(int(value or 10), 20))


def normalize_key(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def normalize_posix_path(value):
    text = str(value or "").replace("\\", "/").strip()
    if not text:
        return ""
    return str(PurePosixPath(text))


def normalize_pack_archive_title(value):
    text = str(value or "")
    text = re.sub(r"\[[^\]]*(?:fixed|fix|repack|proper|v\d+)[^\]]*\]", " ", text, flags=re.I)
    text = re.sub(r"\b(?:fixed|fix|repack|proper)\b", " ", text, flags=re.I)
    text = re.sub(r"\s+", " ", text).strip()
    return normalize_key(text)


def numeric_value(value):
    try:
        return float(value or 0)
    except (TypeError, ValueError):
        return 0.0


def load_pack_bad_archive_history_index():
    try:
        mtime = PACK_BAD_ARCHIVE_HISTORY_FILE.stat().st_mtime
    except OSError:
        PACK_BAD_ARCHIVE_HISTORY_CACHE.update({"mtime": None, "paths": {}, "titles": {}})
        return PACK_BAD_ARCHIVE_HISTORY_CACHE
    if PACK_BAD_ARCHIVE_HISTORY_CACHE.get("mtime") == mtime:
        return PACK_BAD_ARCHIVE_HISTORY_CACHE
    data = read_json_file(PACK_BAD_ARCHIVE_HISTORY_FILE, {}) or {}
    rows = data.get("bad_archives") if isinstance(data, dict) else data
    if not isinstance(rows, list):
        rows = []
    paths = {}
    titles = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        source = normalize_posix_path(row.get("source"))
        if not source:
            continue
        parent = str(PurePosixPath(source).parent)
        title = PurePosixPath(parent).name
        for bucket, key in ((paths, parent), (titles, normalize_pack_archive_title(title))):
            if not key:
                continue
            entry = bucket.setdefault(
                key,
                {
                    "bad_archive_count": 0,
                    "pack_path": parent,
                    "pack_title": title,
                    "sample_sources": [],
                    "last_seen_at": 0,
                },
            )
            entry["bad_archive_count"] += 1
            if len(entry["sample_sources"]) < 3:
                entry["sample_sources"].append(source)
            entry["last_seen_at"] = max(numeric_value(entry.get("last_seen_at")), numeric_value(row.get("ts")))
    PACK_BAD_ARCHIVE_HISTORY_CACHE.update({"mtime": mtime, "paths": paths, "titles": titles})
    return PACK_BAD_ARCHIVE_HISTORY_CACHE


def known_bad_pack_archive_for_ready(ready):
    ready = ready or {}
    selected_path = normalize_posix_path(ready.get("selected_path"))
    title_key = normalize_pack_archive_title(ready.get("title") or PurePosixPath(selected_path).name)
    index = load_pack_bad_archive_history_index()
    candidates = []
    if selected_path:
        candidates.append(index.get("paths", {}).get(selected_path))
    if title_key:
        titles = index.get("titles", {})
        candidates.extend(
            entry
            for key, entry in titles.items()
            if title_key == key or title_key.startswith(key) or key.startswith(title_key)
        )
    candidates = [entry for entry in candidates if isinstance(entry, dict)]
    if not candidates:
        return None
    best = max(candidates, key=lambda entry: int(entry.get("bad_archive_count") or 0))
    if int(best.get("bad_archive_count") or 0) < PACK_BAD_ARCHIVE_AUTO_BLOCK_MIN:
        return None
    return {
        "reason": "known_bad_pack_archive_history",
        "bad_archive_count": int(best.get("bad_archive_count") or 0),
        "pack_path": best.get("pack_path"),
        "pack_title": best.get("pack_title"),
        "sample_sources": best.get("sample_sources") or [],
        "last_seen_at": best.get("last_seen_at"),
    }


_ISSUE_METADATA_CACHE = None


def issue_number_keys(value):
    text = str(value or "").strip()
    keys = {normalize_key(text)}
    match = re.search(r"\d+(?:\.\d+)?", text)
    if match:
        raw = match.group(0)
        keys.add(normalize_key(raw))
        try:
            number = int(float(raw))
            keys.add(str(number))
            keys.add(f"{number:03d}")
        except ValueError:
            pass
    keys.discard("")
    return keys


def issue_metadata_index():
    global _ISSUE_METADATA_CACHE
    if _ISSUE_METADATA_CACHE is not None:
        return _ISSUE_METADATA_CACHE
    data = read_json_file(COMIC_SERIES_FILE, {}) or {}
    watches = data.get("watches") if isinstance(data, dict) else []
    index = {}
    for watch in watches or []:
        if not isinstance(watch, dict):
            continue
        series_keys = {
            normalize_key(value)
            for value in (watch.get("name"), watch.get("title"), watch.get("series"), watch.get("query"))
            if value
        }
        series_keys.discard("")
        rows = []
        known = watch.get("knownIssues")
        if isinstance(known, dict):
            rows.extend(row for row in known.values() if isinstance(row, dict))
        for key in ("missingIssues", "issues", "newIssues"):
            values = watch.get(key)
            if isinstance(values, list):
                rows.extend(row for row in values if isinstance(row, dict))
        for issue in rows:
            number_keys = issue_number_keys(issue.get("issueNumber") or issue.get("issue") or issue.get("number"))
            if not number_keys:
                continue
            record = {
                "title": safe_optional_text(issue.get("title"), 180),
                "date": safe_optional_text(issue.get("date"), 40),
                "search_query": safe_optional_text(issue.get("searchQuery"), 220),
            }
            if not any(record.values()):
                continue
            for series_key in series_keys:
                for number_key in number_keys:
                    index.setdefault((series_key, number_key), record)
    _ISSUE_METADATA_CACHE = index
    return _ISSUE_METADATA_CACHE


def issue_metadata_for_review_item(item):
    number_keys = issue_number_keys((item or {}).get("issue"))
    if not number_keys:
        return {}
    for value in ((item or {}).get("series"), (item or {}).get("query")):
        series_key = normalize_key(value)
        if not series_key:
            continue
        for number_key in number_keys:
            record = issue_metadata_index().get((series_key, number_key))
            if record:
                return record
    return {}


SUPPLEMENTAL_PACK_PHRASES = {
    "adventurer s bible",
    "art book",
    "artbook",
    "character book",
    "companion",
    "encyclopedia",
    "fan book",
    "fanbook",
    "guide book",
    "guidebook",
    "official guide",
    "world guide",
}


def is_supplemental_pack_result(raw_title):
    normalized = normalize_key(raw_title)
    padded = f" {normalized} "
    return any(f" {phrase} " in padded for phrase in SUPPLEMENTAL_PACK_PHRASES)


def is_manga_like_title(title, publisher=None, unit_model=None):
    if unit_model:
        return True
    normalized = normalize_key(title)
    publisher_text = str(publisher or "").lower()
    return normalized in MANGA_TITLE_HINTS or any(hint in publisher_text for hint in MANGA_PUBLISHER_HINTS)


def normalize_manga_number(value):
    match = re.search(r"\d+(?:\.\d+)?", str(value or ""))
    if not match:
        return None
    raw = match.group(0)
    try:
        number = float(raw)
    except ValueError:
        return None
    if number < 0:
        return None
    if number.is_integer():
        return f"{int(number):03d}"
    whole, _, frac = raw.partition(".")
    frac = frac.rstrip("0") or "0"
    return f"{int(whole):03d}.{frac}"


def connect_imported_db(readonly=False):
    if readonly:
        con = sqlite3.connect(f"file:{IMPORTED_DB}?mode=ro", timeout=8, uri=True)
    else:
        con = sqlite3.connect(IMPORTED_DB, timeout=8)
    con.execute(f"pragma busy_timeout={IMPORTED_DB_BUSY_TIMEOUT_MS}")
    return con


def completion_rows(table):
    if not IMPORTED_DB.exists():
        return []
    try:
        con = connect_imported_db(readonly=True)
    except sqlite3.OperationalError:
        return []
    con.row_factory = sqlite3.Row
    try:
        row = con.execute("select name from sqlite_master where type='table' and name=?", (table,)).fetchone()
        if not row:
            return []
        return [dict(item) for item in con.execute(f"select * from {table}")]
    except sqlite3.OperationalError:
        return []
    finally:
        con.close()


def imported_source_paths():
    if not IMPORTED_DB.exists():
        return set()
    try:
        con = connect_imported_db()
    except sqlite3.OperationalError:
        return set()
    try:
        con.execute("create table if not exists imported_files (sha256 text primary key, source text, dest text, size integer, imported_at real)")
        return {str(row[0]) for row in con.execute("select source from imported_files where source is not null")}
    except sqlite3.OperationalError:
        return set()
    finally:
        con.close()


def is_supported_inbox_file(path):
    name = path.name.lower()
    return path.suffix.lower() in MANUAL_INBOX_EXTS or name.endswith(".cbz.zip")


def manual_inbox_summary(path):
    summary = {
        "total": 0,
        "action_needed": 0,
        "already_imported": 0,
        "internal": 0,
        "unsupported": 0,
        "items": [],
    }
    if not path.exists():
        return summary
    imported_sources = imported_source_paths()
    for item in path.rglob("*"):
        if not item.is_file():
            continue
        try:
            relative_parts = item.relative_to(path).parts
        except ValueError:
            relative_parts = item.parts
        if any(part.startswith("_") for part in relative_parts):
            if is_supported_inbox_file(item):
                summary["internal"] += 1
            continue
        if not is_supported_inbox_file(item):
            summary["unsupported"] += 1
            continue
        summary["total"] += 1
        source = str(item)
        if source in imported_sources:
            bucket = "already_imported"
            summary["already_imported"] += 1
        elif item.suffix.lower() == ".pdf":
            bucket = "manual_only"
            summary["action_needed"] += 1
        else:
            bucket = "action_needed"
            summary["action_needed"] += 1
        summary["items"].append({
            "name": item.name,
            "path": source,
            "bucket": bucket,
            "size": item.stat().st_size,
        })
    return summary


def ensure_manga_unit_schema(con):
    con.execute(
        """
        create table if not exists manga_series_unit_model (
          normalized_series text primary key,
          series_title text not null,
          kapowarr_volume_id integer,
          manga_unit_model text not null,
          source text,
          updated_at real not null
        )
        """
    )
    con.execute(
        """
        create table if not exists manga_unit_completion (
          series_title text not null,
          normalized_series text not null,
          kapowarr_volume_id integer,
          kapowarr_issue_id integer,
          issue_number text,
          normalized_number text not null,
          manga_unit_model text not null,
          truth_model text not null,
          target_file_path text not null,
          source_path text,
          sha256 text,
          comicinfo_status text,
          kavita_visibility_status text not null,
          verification_status text not null,
          review_id text,
          completed_at real not null,
          updated_at real not null,
          primary key (normalized_series, normalized_number, manga_unit_model, truth_model)
        )
        """
    )
    ensure_manga_coverage_schema(con)


