def kavita_visible_numbers_cached(context, series_title):
    if not context:
        return kavita_visible_numbers(series_title)
    key = normalize_key(series_title)
    if not key:
        return set()
    cache = context.setdefault("kavita_visible_cache", {})
    if key not in cache:
        cache[key] = kavita_visible_numbers(series_title)
    return cache[key]


def decision_summary_for_watch(watch, context=None):
    name = watch.get("name")
    volume_id = watch.get("kapowarrId")
    missing = int(watch.get("missingIssueCount") or 0)
    suppressed = int(watch.get("suppressedIssueCount") or 0)
    completed = (
        completed_reading_numbers_cached(context, volume_id, name)
        | completed_manga_unit_numbers_cached(context, {"chapter", "mixed_chapter_preferred"}, volume_id, name)
        | kavita_visible_numbers_cached(context, name)
    )
    reconcile = reconciliation_summary_for_series_cached(context, name)
    review = manual_review_count_for_series_cached(context, name)
    active = int(reconcile.get("active_downloads") or 0)
    pending = int(reconcile.get("pending_imports") or 0)
    blocked = int(reconcile.get("blocked") or 0)
    actionable = max(0, missing - active - pending - review - blocked)
    state = "complete"
    if review:
        state = "needs_review"
    elif active:
        state = "active_download"
    elif pending:
        state = "pending_import"
    elif blocked:
        state = "blocked"
    elif actionable:
        state = "actionable"
    return {
        "state": state,
        "actionable": actionable,
        "in_kavita": len(completed),
        "active_downloads": active,
        "pending_imports": pending,
        "ready_imports": int(reconcile.get("ready_imports") or 0),
        "waiting_for_scan": int(reconcile.get("waiting_for_scan") or 0),
        "review": review,
        "blocked": blocked,
        "failed": int(reconcile.get("failed") or 0),
        "stale": int(reconcile.get("stale") or 0),
        "suppressed": suppressed + int(reconcile.get("suppressed") or 0),
    }


def kavita_visible_numbers(series_title):
    """Numbers Kavita currently sees for a series, independent of Kapowarr linkage."""
    if not KAVITA_DB.exists() or not series_title:
        return set()
    series_norm = normalize_key(series_title)
    if not series_norm:
        return set()
    con = sqlite3.connect(KAVITA_DB)
    con.row_factory = sqlite3.Row
    try:
        rows = con.execute(
            """
            select s.Name as series_name, s.NormalizedName as normalized_name,
                   v.Number as volume_number, v.Name as volume_name,
                   c.Number as chapter_number, c.Range as chapter_range,
                   c.MinNumber as min_number, c.MaxNumber as max_number,
                   mf.FilePath as file_path
            from Series s
            join Volume v on v.SeriesId = s.Id
            join Chapter c on c.VolumeId = v.Id
            join MangaFile mf on mf.ChapterId = c.Id
            where lower(coalesce(s.NormalizedName, s.Name, '')) = ?
               or lower(coalesce(s.Name, '')) = ?
               or lower(coalesce(s.OriginalName, '')) = ?
            """,
            (series_norm, str(series_title).lower(), str(series_title).lower()),
        ).fetchall()
    finally:
        con.close()
    numbers = set()
    for row in rows:
        candidates = [
            row["chapter_number"],
            row["chapter_range"],
            row["volume_number"],
            row["volume_name"],
            row["min_number"],
            row["max_number"],
        ]
        for value in candidates:
            number = normalize_manga_number(value)
            if number:
                numbers.add(number)
    return numbers


def load_watches():
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    if not WATCHES_FILE.exists():
        return {"watches": [], "updated": None}
    # ValueError, not just JSONDecodeError: a file that is not valid UTF-8
    # raises UnicodeDecodeError, which is a ValueError but NOT a
    # JSONDecodeError, so it walked straight past the narrower catch. The
    # isinstance check covers the other half -- a file whose root is a list,
    # a string or null parses fine and then raises AttributeError on
    # setdefault, from a line that looks like it cannot fail.
    try:
        data = json.loads(WATCHES_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        print(f"InkDrop could not read {WATCHES_FILE}: {exc}", flush=True)
        return {"watches": [], "updated": None}
    if not isinstance(data, dict):
        print(f"InkDrop ignored {WATCHES_FILE}: expected an object, found {type(data).__name__}", flush=True)
        return {"watches": [], "updated": None}
    data.setdefault("watches", [])
    return data


def save_watches(data):
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    data["updated"] = time.time()
    tmp = WATCHES_FILE.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(data, indent=2, sort_keys=True), encoding="utf-8")
    tmp.replace(WATCHES_FILE)


def watch_log(event, payload):
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    safe = dict(payload)
    safe["event"] = event
    safe["ts"] = time.time()
    with WATCH_LOG.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(safe, sort_keys=True) + "\n")


