def public_comic_watch_from_series_row(row):
    row = row if isinstance(row, dict) else {}
    metadata_provider = str(row.get("metadata_provider") or row.get("source") or "").strip().lower()
    metadata_id = str(row.get("metadata_id") or "").strip()
    comicvine_id = metadata_id if metadata_provider in {"comicvine", "cv"} and metadata_id.isdigit() else ""
    wanted = int(row.get("wanted_count") or 0)
    active = int(row.get("active_queue_count") or 0)
    downloading = int(row.get("downloading_count") or 0)
    importing = int(row.get("importing_count") or 0)
    needs_you = int(row.get("needs_you_count") or 0)
    provider_wait = int(row.get("provider_wait_count") or 0)
    reader_visible = int(row.get("reader_visibility_visible_count") or 0)
    reader_lag = int(row.get("reader_visibility_lag_count") or 0)
    reader_unaccounted = int(row.get("reader_visibility_unaccounted_count") or 0)
    reader_gap = int(row.get("reader_visibility_gap_count") or reader_lag)
    reader_applicable = bool(row.get("reader_completion_applicable"))
    reader_blocked = int(row.get("reader_visibility_blocked_count") or 0)
    reader_required = int(row.get("reader_visibility_required_count") or 0)
    reader_pending = int(row.get("reader_visibility_pending_count") or 0)
    reader_optional = int(row.get("reader_visibility_optional_count") or 0)
    reader_timeout = int(row.get("reader_visibility_timeout_count") or 0)
    acquisition_complete = not (needs_you or active or wanted or provider_wait)
    state = "complete"
    if needs_you:
        state = "needs_review"
    elif downloading:
        state = "active_download"
    elif importing:
        state = "pending_import"
    elif active:
        state = "active_download"
    elif wanted or provider_wait:
        state = "actionable"
    elif reader_gap:
        state = "reader_pending"
    decision = {
        "state": state,
        "actionable": wanted,
        "in_kavita": reader_visible,
        "active_downloads": active,
        "pending_imports": importing,
        "ready_imports": 0,
        "waiting_for_scan": 0,
        "review": needs_you,
        "blocked": 0,
        "failed": 0,
        "stale": 0,
        "suppressed": 0,
        "acquisition_complete": acquisition_complete,
        "reader_complete": (acquisition_complete and reader_gap == 0) if reader_applicable else None,
        "reader_completion_applicable": reader_applicable,
        "reader_visibility_lag_count": reader_lag,
        "reader_visibility_unaccounted_count": reader_unaccounted,
        "reader_visibility_gap_count": reader_gap,
        "reader_visibility_blocked_count": reader_blocked,
        "reader_visibility_required_count": reader_required,
        "reader_visibility_pending_count": reader_pending,
        "reader_visibility_optional_count": reader_optional,
        "reader_visibility_timeout_count": reader_timeout,
        "reader_visibility_note": row.get("reader_visibility_note") or "",
        "reader_visibility_next_action": row.get("reader_visibility_next_action") or "",
    }
    return {
        "id": row.get("id") or row.get("series_id") or "",
        "comicvineId": comicvine_id,
        "name": row.get("title") or "Unknown series",
        "year": row.get("year") or row.get("start_year"),
        "publisher": row.get("publisher"),
        "issueCount": row.get("issue_count"),
        "siteUrl": row.get("site_url"),
        "image": row.get("image"),
        "source": row.get("source") or metadata_provider or "inkdrop",
        "owner": row.get("owner") or row.get("ownership") or "inkdrop",
        "ownership": row.get("ownership") or "native",
        "metadataProvider": metadata_provider,
        "metadataAdapter": row.get("metadata_adapter") or row.get("metadataAdapter"),
        "metadataAdapterRole": row.get("metadata_adapter_role") or row.get("metadataAdapterRole"),
        "kapowarrId": row.get("kapowarr_id"),
        "kapowarrRole": row.get("kapowarrRole"),
        "enabled": bool(row.get("monitored", True)),
        "autoGrab": bool(row.get("auto_grab", True)),
        "created": row.get("created_at"),
        "lastScan": row.get("updated_at"),
        "lastError": None,
        "knownIssueCount": int(row.get("issue_count") or 0),
        "newIssues": [],
        "missingIssueCount": wanted,
        "missingIssueTotal": wanted,
        "missingIssues": [],
        "suppressedIssueCount": 0,
        "suppressedIssues": [],
        "decisionSummary": decision,
        "kavitaVisibleIssueCount": reader_visible,
        "kavitaVisibleSuppressedCount": 0,
    }


def public_comic_watches_fast_payload(limit=300):
    now = time.time()
    with COMICVINE_WATCHES_CACHE_LOCK:
        cached = COMICVINE_WATCHES_CACHE.get("payload")
        cached_at = float(COMICVINE_WATCHES_CACHE.get("ts") or 0)
        if isinstance(cached, dict) and now - cached_at <= COMICVINE_WATCHES_CACHE_TTL_SECONDS:
            payload = json.loads(json.dumps(cached))
            payload["cache"] = "hit"
            payload["cache_age_seconds"] = round(now - cached_at, 3)
            return payload
        rows = inkdrop_state.series_compact_card_rows(INKDROP_STATE_DB, limit, series_filter="all")
        watches = [public_comic_watch_from_series_row(row) for row in rows]
        payload = {
            "ok": True,
            "watches": watches,
            "updated": now,
            "source": "inkdrop_series_compact",
            "cache": "miss",
            "cache_age_seconds": 0,
        }
        COMICVINE_WATCHES_CACHE.update({"ts": now, "payload": json.loads(json.dumps(payload))})
        return payload


