def completed_pack_manifest_cache_summary(limit=5):
    if not IMPORTED_DB.exists():
        return {"ok": False, "reason": "imported_db_missing", "root_count": 0, "archive_count": 0}
    try:
        conn = sqlite3.connect(IMPORTED_DB, timeout=2)
        conn.row_factory = sqlite3.Row
        try:
            exists = conn.execute(
                "select name from sqlite_master where type=? and name=?",
                ("table", "completed_pack_manifests"),
            ).fetchone()
            if not exists:
                return {"ok": True, "root_count": 0, "archive_count": 0, "truncated_count": 0, "sample_roots": []}
            row = conn.execute(
                """
                select count(*) as root_count,
                       coalesce(sum(archive_count), 0) as archive_count,
                       coalesce(sum(case when truncated then 1 else 0 end), 0) as truncated_count,
                       max(scanned_at) as newest_scanned_at,
                       min(scanned_at) as oldest_scanned_at
                from completed_pack_manifests
                """
            ).fetchone()
            sample_rows = conn.execute(
                """
                select root_path, archive_count, cached_limit, truncated, scanned_at
                from completed_pack_manifests
                order by coalesce(scanned_at, 0) desc
                limit ?
                """,
                (max(1, int(limit or 5)),),
            ).fetchall()
        finally:
            conn.close()
    except Exception as exc:
        return {"ok": False, "reason": "cache_read_failed", "error": f"{type(exc).__name__}: {exc}", "root_count": 0, "archive_count": 0}

    current = time.time()

    def age_minutes(ts):
        try:
            return round((current - float(ts)) / 60, 1)
        except (TypeError, ValueError):
            return None

    root_count = int(row["root_count"] or 0) if row else 0
    archive_count = int(row["archive_count"] or 0) if row else 0
    truncated_count = int(row["truncated_count"] or 0) if row else 0
    newest = row["newest_scanned_at"] if row else None
    oldest = row["oldest_scanned_at"] if row else None
    return {
        "ok": True,
        "root_count": root_count,
        "archive_count": archive_count,
        "truncated_count": truncated_count,
        "newest_scanned_at": newest,
        "oldest_scanned_at": oldest,
        "newest_age_minutes": age_minutes(newest),
        "oldest_age_minutes": age_minutes(oldest),
        "sample_roots": [
            {
                "root_path": item["root_path"],
                "archive_count": int(item["archive_count"] or 0),
                "cached_limit": int(item["cached_limit"] or 0),
                "truncated": bool(item["truncated"]),
                "scanned_at": item["scanned_at"],
                "age_minutes": age_minutes(item["scanned_at"]),
            }
            for item in sample_rows
        ],
    }


