def inkdrop_series_cover_refresh_candidate_id(row):
    row = row if isinstance(row, dict) else {}
    provider = str(row.get("metadata_provider") or row.get("metadataProvider") or row.get("source") or "").strip().lower()
    metadata_id = str(row.get("metadata_id") or row.get("metadataId") or row.get("comicvineId") or row.get("comicvine_id") or "").strip()
    if metadata_id.isdigit() and (provider in {"", "comicvine", "cv"} or str(row.get("id") or "").startswith("comicvine:")):
        return metadata_id
    match = re.match(r"^comicvine:(\d+)$", str(row.get("series_id") or row.get("id") or "").strip(), re.I)
    return match.group(1) if match else ""


def refresh_inkdrop_series_cover_metadata(payload):
    payload = payload if isinstance(payload, dict) else {}
    try:
        limit = int(payload.get("limit") or 8)
    except (TypeError, ValueError):
        limit = 8
    limit = max(1, min(limit, 20))
    requested_ids = {
        str(value or "").strip()
        for value in (
            payload.get("seriesIds")
            or payload.get("series_ids")
            or ([payload.get("seriesId")] if payload.get("seriesId") else [])
            or []
        )
        if str(value or "").strip()
    }
    rows = inkdrop_state.series_rows(INKDROP_STATE_DB, 300, series_filter="all")
    candidates = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        row_id = str(row.get("id") or row.get("series_id") or "").strip()
        cv_id = inkdrop_series_cover_refresh_candidate_id(row)
        if requested_ids and row_id not in requested_ids and cv_id not in requested_ids and f"comicvine:{cv_id}" not in requested_ids:
            continue
        has_display_metadata = bool(row.get("description") or row.get("deck") or row.get("site_url") or row.get("issue_count"))
        if (row.get("image") and has_display_metadata) or not cv_id:
            continue
        candidates.append((row, cv_id))
        if len(candidates) >= limit:
            break

    results = []
    refreshed = 0
    skipped = 0
    errors = 0
    for row, cv_id in candidates:
        row_id = str(row.get("id") or row.get("series_id") or "").strip()
        title = row.get("title") or row_id
        try:
            volume = comicvine_fetch_volume(cv_id, timeout=6, attempts=1)
            image = str(volume.get("image") or "").strip()
            result = inkdrop_state.update_series_display_metadata(
                INKDROP_STATE_DB,
                row_id,
                {"volume": volume, "reason": payload.get("reason") or "series_display_metadata_refresh"},
                source="comicvine",
            )
            if result.get("updated"):
                refreshed += 1
            else:
                skipped += 1
            results.append({
                "series_id": row_id,
                "title": title,
                "comicvine_id": cv_id,
                "updated": bool(result.get("updated")),
                "reason": result.get("reason"),
                "image": result.get("image") or image,
                "metadata": result.get("metadata") or {},
            })
        except Exception as exc:
            errors += 1
            results.append({
                "series_id": row_id,
                "title": title,
                "comicvine_id": cv_id,
                "updated": False,
                "reason": f"{type(exc).__name__}: {exc}",
            })
    return {
        "ok": errors == 0 or refreshed > 0 or skipped > 0,
        "requested": len(requested_ids),
        "candidates": len(candidates),
        "refreshed": refreshed,
        "skipped": skipped,
        "errors": errors,
        "results": results,
    }


def payload_list_values(payload, *keys):
    payload = payload if isinstance(payload, dict) else {}
    out = []
    for key in keys:
        value = payload.get(key)
        if isinstance(value, (list, tuple, set)):
            values = value
        elif value in (None, ""):
            values = []
        else:
            values = [value]
        for item in values:
            text = str(item or "").strip()
            if text:
                out.append(text)
    return out


def managed_folder_for_frontend_sync(path_value, roots):
    text = str(path_value or "").strip()
    if not text:
        return None, "empty_path"
    path = Path(text)
    folder = path.parent if path.suffix else path
    try:
        resolved = folder.resolve(strict=False)
    except Exception:
        resolved = folder
    for root in roots or []:
        if not root:
            continue
        try:
            root_path = Path(str(root)).resolve(strict=False)
            resolved.relative_to(root_path)
            return str(folder), ""
        except Exception:
            continue
    return None, "outside_managed_roots"


def frontend_sync_folder_candidates(payload):
    payload = payload if isinstance(payload, dict) else {}
    settings = inkdrop_state.media_management_settings_context(INKDROP_STATE_DB)
    roots = [settings.get("comic_root"), settings.get("manga_root")]
    series_ids = payload_list_values(payload, "seriesId", "series_id", "seriesIds", "series_ids")
    import_ids = payload_list_values(payload, "importId", "import_id", "importIds", "import_ids")
    direct_folders = payload_list_values(payload, "folder", "folders", "path", "paths")
    folders = []
    skipped = []

    def add_candidate(value, source):
        folder, reason = managed_folder_for_frontend_sync(value, roots)
        if folder:
            folders.append(folder)
        elif value:
            skipped.append({"source": source, "path": str(value), "reason": reason})

    for folder in direct_folders:
        add_candidate(folder, "payload")

    for series_id in series_ids:
        item = inkdrop_state.series_item(INKDROP_STATE_DB, series_id)
        if item and item.get("library_path"):
            add_candidate(item.get("library_path"), "series_library_path")

    where = []
    params = []
    if series_ids:
        where.append("series_id in ({})".format(",".join("?" for _ in series_ids)))
        params.extend(series_ids)
    if import_ids:
        where.append("id in ({})".format(",".join("?" for _ in import_ids)))
        params.extend(import_ids)
    if where:
        try:
            with sqlite3.connect(INKDROP_STATE_DB) as con:
                con.row_factory = sqlite3.Row
                rows = con.execute(
                    f"""
                    select id, series_id, dest_path, status, completion_truth,
                           folder_imported, library_visibility_status, verified, created_at
                    from import_results
                    where ({' or '.join(where)})
                      and coalesce(dest_path, '') <> ''
                      and (
                        coalesce(folder_imported, 0)=1
                        or lower(coalesce(completion_truth, '')) = 'folder'
                        or coalesce(verified, 0)=1
                        or lower(coalesce(status, '')) in (
                          'folder_verified',
                          'waiting_for_library_scan',
                          'waiting_for_kavita_scan',
                          'library_scan_timeout',
                          'kavita_scan_timeout',
                          'library_visible'
                        )
                      )
                    order by coalesce(created_at, 0) desc, id desc
                    limit 250
                    """,
                    params,
                ).fetchall()
        except sqlite3.Error as exc:
            skipped.append({"source": "import_results", "reason": f"sqlite_error:{exc}"})
            rows = []
        for row in rows:
            add_candidate(row["dest_path"], f"import_result:{row['id']}")

    return {
        "folders": inkdrop_library_frontends.unique_folders(folders)[:25],
        "skipped": skipped[:25],
        "series_ids": series_ids,
        "import_ids": import_ids,
        "roots": roots,
    }


def completed_import_adapter_scan_enabled(module, provider_id):
    try:
        if hasattr(module, "provider_enabled"):
            return bool(module.provider_enabled(provider_id, provider_id == "kavita"))
    except Exception:
        pass
    if provider_id == "kavita":
        return bool(getattr(module, "KAVITA_DB", KAVITA_DB).exists())
    return True


def run_inkdrop_library_frontend_sync(payload):
    payload = payload if isinstance(payload, dict) else {}
    candidates = frontend_sync_folder_candidates(payload)
    folders = candidates.get("folders") or []
    force_library_scan = inkdrop_bool_value(payload.get("forceLibraryScan", payload.get("force_library_scan")), False)
    if not folders:
        return {
            "ok": False,
            "reason": "no_managed_folders_for_frontend_sync",
            "candidate": candidates,
        }
    importer = _inkdrop_completed_import_module()
    if hasattr(importer, "apply_path_provider_settings"):
        importer.apply_path_provider_settings()
    force_folders = folders if force_library_scan else []
    sync = inkdrop_library_frontends.sync_library_frontends(
        folders,
        frontend_sync_enabled=True,
        kavita_scan_enabled=completed_import_adapter_scan_enabled(importer, "kavita"),
        trigger_kavita_scan=getattr(importer, "trigger_kavita_scan_folder", None),
        load_komga_settings=getattr(importer, "load_komga_settings", None),
        trigger_komga_scan=getattr(importer, "trigger_komga_scan_folder", None),
        force_library_scan_folders=force_folders,
        log_event=getattr(importer, "log", None),
        event_prefix="operator_",
    )
    raw = {
        "status": "requested",
        "folders": folders,
        "force_library_scan": force_library_scan,
        "candidate": candidates,
        "sync": sync,
    }
    history = []
    for series_id in candidates.get("series_ids") or []:
        history.append(
            inkdrop_state.record_history_event(
                INKDROP_STATE_DB,
                event_type="library_frontend_sync_requested",
                entity_type="series",
                entity_id=series_id,
                series_id=series_id,
                source="web",
                message=f"Reader frontend sync requested for {len(folders)} folder{'s' if len(folders) != 1 else ''}.",
                raw=raw,
                timeout_seconds=10,
            )
        )
    if not history:
        history.append(
            inkdrop_state.record_history_event(
                INKDROP_STATE_DB,
                event_type="library_frontend_sync_requested",
                entity_type="provider",
                entity_id="library_frontends",
                source="web",
                message=f"Reader frontend sync requested for {len(folders)} folder{'s' if len(folders) != 1 else ''}.",
                raw=raw,
                timeout_seconds=10,
            )
        )
    return {
        "ok": True,
        "folders": folders,
        "force_library_scan": force_library_scan,
        "requested": int(sync.get("requested") or 0),
        "errors": sync.get("errors") or [],
        "sync": sync,
        "candidate": candidates,
        "history": history,
    }


def inkdrop_state_view_public(view, limit=80, source_filter=None, provider_filter=None, queue_filter=None, wanted_filter=None, series_filter=None, issue_filter=None, history_filter=None, import_filter=None, download_filter=None, manual_review_filter=None, focus=None, summary_mode=None, row_mode=None, offset=0, sort_key=None, sort_direction=None):
    started_at = time.perf_counter()
    try:
        view = str(view or "").strip().lower()
        limit_cap = 5000 if view == "series" else 300
        limit = max(1, min(int(limit or 80), limit_cap))
        summary_key = str(summary_mode or "").strip().lower().replace("-", "_")
        queue_wanted_policy = inkdrop_web_state_views.queue_wanted_compact_policy(
            view,
            summary_mode=summary_mode,
            row_mode=row_mode,
            focus=focus,
        )
        def attach_performance(payload, *, route):
            if isinstance(payload, dict):
                payload["state_view_performance"] = {
                    "route": route,
                    "elapsed_ms": round((time.perf_counter() - started_at) * 1000, 1),
                    "summary_mode": summary_key or None,
                    "row_mode": inkdrop_state.normalize_state_view_row_mode(row_mode),
                    "limit": limit,
                    "compact_policy": {
                        "broad_compact_load": bool(queue_wanted_policy.get("broad_compact_load")),
                        "run_settlement": bool(queue_wanted_policy.get("run_settlement")),
                        "live_slskd": bool(queue_wanted_policy.get("live_slskd")),
                        "live_prowlarr": bool(queue_wanted_policy.get("live_prowlarr")),
                        "live_download_clients": bool(queue_wanted_policy.get("live_download_clients")),
                    },
                }
            return payload
        if view == "series" and summary_key in {"compact", "minimal"}:
            payload = inkdrop_series_compact_view_public(
                limit=limit,
                series_filter=series_filter,
                focus=focus,
                summary_mode=summary_mode,
                row_mode=row_mode,
            )
            return attach_performance(payload, route="series_compact")
        if view in {"manual_review", "manual-review", "manual"} and summary_key in {"compact", "minimal"}:
            payload = inkdrop_manual_review_compact_view_public(
                limit=limit,
                manual_review_filter=manual_review_filter,
                focus=focus,
                summary_mode=summary_mode,
                row_mode=row_mode,
            )
            return attach_performance(payload, route="manual_review_compact")
        if view in {"manual_review", "manual-review", "manual"}:
            sync_legacy_manual_review_exceptions()
        if view in {"queue", "wanted", "download_tasks", "downloads", "transfers", "imports", "import_results"} and queue_wanted_policy.get("run_settlement", True):
            settlement = inkdrop_settle_verified_queue_best_effort()
        else:
            settlement = None
        payload = inkdrop_state.state_view(
            INKDROP_STATE_DB,
            view,
            limit=limit,
            source_filter=source_filter,
            provider_filter=provider_filter,
            queue_filter=queue_filter,
            wanted_filter=wanted_filter,
            series_filter=series_filter,
            issue_filter=issue_filter,
            history_filter=history_filter,
            import_filter=import_filter,
            download_filter=download_filter,
            manual_review_filter=manual_review_filter,
            focus=focus,
            summary_mode=summary_mode,
            row_mode=row_mode,
            offset=offset,
            sort_key=sort_key,
            sort_direction=sort_direction,
        )
        if isinstance(settlement, dict) and settlement.get("skipped"):
            payload["queue_settlement"] = settlement
        if view in {"queue", "wanted"}:
            payload = apply_source_health_to_rows(
                payload,
                source_health_summary(
                    live_slskd=bool(queue_wanted_policy.get("live_slskd")),
                    live_prowlarr=bool(queue_wanted_policy.get("live_prowlarr")),
                    live_download_clients=bool(queue_wanted_policy.get("live_download_clients")),
                ),
            )
        return attach_performance(payload, route="state_view")
    except Exception as exc:
        return {
            "ok": False,
            "view": str(view or ""),
            "error": str(exc),
            "db_path": str(INKDROP_STATE_DB),
        }


def inkdrop_history_event_raw(event_id):
    event_id = str(event_id or "").strip()
    if not event_id:
        return {"ok": False, "reason": "missing_id", "id": event_id}
    if not INKDROP_STATE_DB.exists():
        return {
            "ok": False,
            "reason": "state_db_missing",
            "id": event_id,
            "db_path": str(INKDROP_STATE_DB),
        }

    try:
        db_uri = f"file:{INKDROP_STATE_DB}?mode=ro"
        with sqlite3.connect(db_uri, uri=True, timeout=1.0) as con:
            con.row_factory = sqlite3.Row
            con.execute("pragma query_only = 1")
            con.execute("pragma busy_timeout = 250")
            columns = {row["name"] for row in con.execute("pragma table_info(history_events)").fetchall()}
            required = [
                "id",
                "event_type",
                "source",
                "message",
                "created_at",
                "raw_json",
            ]
            optional = ("series_id", "issue_id", "queue_id", "wanted_id", "source_attempt_id", "download_task_id")
            selected = list(required)
            for name in optional:
                if name in columns:
                    selected.append(name)
            row = con.execute(
                f"select {', '.join(selected)} from history_events where id = ?",
                (event_id,),
            ).fetchone()
        if row is None:
            return {"ok": False, "reason": "history_event_not_found", "id": event_id}
    except Exception as exc:
        return {"ok": False, "reason": f"{type(exc).__name__}: {exc}", "id": event_id}

    row_keys = set(row.keys())
    raw_json = row["raw_json"] if "raw_json" in row_keys else None
    raw = None
    raw_parse_error = False
    if raw_json not in (None, ""):
        try:
            raw = json.loads(raw_json)
        except Exception:
            raw_parse_error = True
            raw = None

    def row_value(column):
        return row[column] if column in row_keys else None

    return {
        "ok": True,
        "id": row_value("id"),
        "event_type": row_value("event_type"),
        "source": row_value("source"),
        "message": row_value("message"),
        "created_at": row_value("created_at"),
        "series_id": row_value("series_id"),
        "issue_id": row_value("issue_id"),
        "queue_id": row_value("queue_id"),
        "wanted_id": row_value("wanted_id"),
        "source_attempt_id": row_value("source_attempt_id"),
        "download_task_id": row_value("download_task_id"),
        "raw": raw,
        "raw_json": raw_json if raw_parse_error else None,
        "raw_available": bool(raw_json),
        "raw_parse_error": raw_parse_error,
    }


def normalize_series_autopilot_source_order(value):
    if isinstance(value, str):
        raw = [part.strip() for part in value.split(",")]
    elif isinstance(value, list):
        raw = value
    else:
        raw = []
    order = []
    seen = set()
    for source in raw:
        source = str(source or "").strip().lower()
        if source not in SERIES_AUTOPILOT_VALID_SOURCES or source in seen:
            continue
        order.append(source)
        seen.add(source)
    for source in SERIES_AUTOPILOT_DEFAULT_SOURCE_ORDER:
        if source not in seen:
            order.append(source)
            seen.add(source)
    return order or list(SERIES_AUTOPILOT_DEFAULT_SOURCE_ORDER)


def normalize_provider_source_order(value, default_order):
    if isinstance(value, str):
        raw = [part.strip() for part in value.split(",")]
    elif isinstance(value, list):
        raw = value
    else:
        raw = []
    order = []
    seen = set()
    for source in raw:
        source = str(source or "").strip().lower()
        if source not in SERIES_AUTOPILOT_VALID_SOURCES or source in seen:
            continue
        order.append(source)
        seen.add(source)
    for source in default_order or []:
        source = str(source or "").strip().lower()
        if source in SERIES_AUTOPILOT_VALID_SOURCES and source not in seen:
            order.append(source)
            seen.add(source)
    return order or [source for source in default_order or [] if source in SERIES_AUTOPILOT_VALID_SOURCES]


def normalize_mangadex_source_order(value):
    return normalize_provider_source_order(value, ["mangadex", "slskd", "prowlarr", "rss"])


def normalize_comicvine_source_order(value):
    return normalize_provider_source_order(value, ["local", "prowlarr", "rss", "slskd"])


def normalize_protocol_order(value):
    if isinstance(value, str):
        raw = [part.strip() for part in value.split(",")]
    elif isinstance(value, list):
        raw = value
    else:
        raw = []
    aliases = {
        "nzb": "usenet",
        "nzbs": "usenet",
        "sab": "usenet",
        "sabnzbd": "usenet",
        "usenet": "usenet",
        "torrent": "torrent",
        "torrents": "torrent",
        "qbit": "torrent",
        "qbittorrent": "torrent",
        "qb": "torrent",
    }
    order = []
    seen = set()
    for item in raw:
        protocol = aliases.get(str(item or "").strip().lower(), str(item or "").strip().lower())
        if protocol not in {"usenet", "torrent"} or protocol in seen:
            continue
        order.append(protocol)
        seen.add(protocol)
    for protocol in ("usenet", "torrent"):
        if protocol not in seen:
            order.append(protocol)
    return order or ["usenet", "torrent"]


def configured_protocol_order():
    try:
        setting = inkdrop_state.app_setting(INKDROP_STATE_DB, "automation.protocol_order") or {}
        return normalize_protocol_order(setting.get("value"))
    except Exception:
        return ["usenet", "torrent"]


def configured_comicvine_source_order():
    try:
        config = inkdrop_state.provider_config(INKDROP_STATE_DB, "comicvine") or {}
        settings = config.get("settings") if isinstance(config.get("settings"), dict) else {}
        return normalize_comicvine_source_order(settings.get("source_order"))
    except Exception:
        return normalize_comicvine_source_order(None)


def configured_series_autopilot_source_order():
    try:
        setting = inkdrop_state.app_setting(INKDROP_STATE_DB, "automation.source_order") or {}
        return normalize_series_autopilot_source_order(setting.get("value"))
    except Exception:
        return list(SERIES_AUTOPILOT_DEFAULT_SOURCE_ORDER)


def source_order_policy_summary(source_order=None, provider_health=None):
    order = normalize_series_autopilot_source_order(source_order or configured_series_autopilot_source_order())
    acquisition_order = [source for source in order if source != "local"]
    source_counts = {}
    provider_outcomes = {}
    order_counts = {}
    row_policy_coverage = {
        "empty_policy_rows": 0,
        "current_global_order_rows": 0,
        "row_specific_policy_rows": 0,
        "slskd_first_rows": 0,
        "mangadex_first_rows": 0,
        "mangadex_metadata_rows": 0,
        "mangadex_metadata_without_row_policy_rows": 0,
        "mangadex_metadata_without_slskd_or_mangadex_first_rows": 0,
    }
    active_queued = 0
    error = ""
    current_order_key = ",".join(order)

    def clean_source_list(values):
        out = []
        for value in values or []:
            text = str(value or "").strip().lower()
            if text and text not in out:
                out.append(text)
        return out

    def first_acquisition(values):
        for value in values or []:
            text = str(value or "").strip().lower()
            if text and text != "local":
                return text
        return ""

    if inkdrop_state is None or not INKDROP_STATE_DB.exists():
        error = "InkDrop state database is not available."
    else:
        try:
            db_uri = f"file:{INKDROP_STATE_DB}?mode=ro"
            with sqlite3.connect(db_uri, uri=True, timeout=0.25) as con:
                con.row_factory = sqlite3.Row
                con.execute("pragma query_only = 1")
                con.execute("pragma busy_timeout = 250")
                for row in con.execute(
                    """
                    select q.source_order_json, q.recovery_steps_json, q.current_source, q.last_event,
                           coalesce(s.metadata_provider, '') as series_metadata_provider,
                           coalesce(i.metadata_provider, '') as issue_metadata_provider
                    from queue_items q
                    left join series s on s.id = q.series_id
                    left join issues i on i.id = q.issue_id
                    where q.active = 1 and q.state = 'queued'
                    """
                ):
                    active_queued += 1
                    plan = inkdrop_state.source_plan_from_values(
                        row["source_order_json"],
                        row["recovery_steps_json"],
                        row["current_source"],
                        row["last_event"],
                    )
                    source = str(
                        plan.get("next_acquisition_source")
                        or plan.get("next_concrete_source")
                        or plan.get("next_source")
                        or "source_ladder"
                    ).strip().lower()
                    if source:
                        source_counts[source] = int(source_counts.get(source) or 0) + 1
                    row_order = clean_source_list(plan.get("source_order") or [])
                    has_row_policy = bool(str(row["source_order_json"] or "").strip() not in {"", "[]", "null"})
                    effective_order = row_order or list(order)
                    order_key = ",".join(effective_order) or "(empty)"
                    order_counts[order_key] = int(order_counts.get(order_key) or 0) + 1
                    first_source = first_acquisition(effective_order)
                    is_mangadex_metadata = (
                        str(row["series_metadata_provider"] or "").strip().lower() == "mangadex"
                        or str(row["issue_metadata_provider"] or "").strip().lower() == "mangadex"
                    )
                    if not has_row_policy:
                        row_policy_coverage["empty_policy_rows"] += 1
                    if not has_row_policy or order_key == current_order_key:
                        row_policy_coverage["current_global_order_rows"] += 1
                    else:
                        row_policy_coverage["row_specific_policy_rows"] += 1
                    if first_source == "slskd":
                        row_policy_coverage["slskd_first_rows"] += 1
                    if first_source == "mangadex":
                        row_policy_coverage["mangadex_first_rows"] += 1
                    if is_mangadex_metadata:
                        row_policy_coverage["mangadex_metadata_rows"] += 1
                        if not has_row_policy:
                            row_policy_coverage["mangadex_metadata_without_row_policy_rows"] += 1
                        if first_source not in {"slskd", "mangadex"}:
                            row_policy_coverage["mangadex_metadata_without_slskd_or_mangadex_first_rows"] += 1
        except Exception as exc:
            error = str(exc)

    next_sources = [
        {
            "source": source,
            "label": inkdrop_state.source_display_label(source),
            "count": int(count),
        }
        for source, count in sorted(source_counts.items(), key=lambda item: (-int(item[1] or 0), item[0]))
    ]
    top_source_orders = []
    for key, count in sorted(order_counts.items(), key=lambda item: (-int(item[1] or 0), item[0]))[:8]:
        values = [] if key == "(empty)" else [part for part in key.split(",") if part]
        top_source_orders.append(
            {
                "source_order": values,
                "source_order_labels": [inkdrop_state.source_display_label(value) for value in values],
                "first_acquisition_source": first_acquisition(values),
                "first_acquisition_source_label": inkdrop_state.source_display_label(first_acquisition(values)) if first_acquisition(values) else "",
                "count": int(count),
                "matches_current_order": key == current_order_key,
            }
        )
    row_policy_chips = []
    if active_queued > 0:
        row_policy_chips.append(f"Global order rows: {int(row_policy_coverage.get('current_global_order_rows') or 0)}")
        row_policy_chips.append(f"Row-specific order: {int(row_policy_coverage.get('row_specific_policy_rows') or 0)}")
        if int(row_policy_coverage.get("slskd_first_rows") or 0):
            row_policy_chips.append(f"SLSKD first rows: {int(row_policy_coverage.get('slskd_first_rows') or 0)}")
        if int(row_policy_coverage.get("mangadex_first_rows") or 0):
            row_policy_chips.append(f"MangaDex first rows: {int(row_policy_coverage.get('mangadex_first_rows') or 0)}")
        if int(row_policy_coverage.get("mangadex_metadata_rows") or 0):
            row_policy_chips.append(f"MangaDex metadata rows: {int(row_policy_coverage.get('mangadex_metadata_rows') or 0)}")
    provider_health = provider_health if isinstance(provider_health, dict) else {}
    health_rows = []
    seen_health = set()
    for source in acquisition_order:
        key = inkdrop_state.provider_activity_key(source)
        health = provider_health.get(key) if isinstance(provider_health.get(key), dict) else {}
        if not health:
            continue
        seen_health.add(key)
        state = str(health.get("state") or health.get("outcome") or "unknown").strip().lower()
        health_rows.append(
            {
                "provider": key,
                "label": inkdrop_state.source_display_label(key),
                "state": state,
                "state_label": str(health.get("label") or state.replace("_", " ")).strip(),
                "detail": str(health.get("detail") or "").strip(),
            }
        )
    for key in ("slskd", "prowlarr", "rss", "comicscodes"):
        if key in seen_health:
            continue
        health = provider_health.get(key) if isinstance(provider_health.get(key), dict) else {}
        if not health:
            continue
        state = str(health.get("state") or health.get("outcome") or "unknown").strip().lower()
        health_rows.append(
            {
                "provider": key,
                "label": inkdrop_state.source_display_label(key),
                "state": state,
                "state_label": str(health.get("label") or state.replace("_", " ")).strip(),
                "detail": str(health.get("detail") or "").strip(),
            }
        )

    problem_states = {"watch", "backoff", "unavailable", "disabled", "error", "failed", "degraded"}
    problem_health = next((row for row in health_rows if row.get("state") in problem_states), None)
    dominant = next_sources[0] if next_sources else {}
    current_order_label = " -> ".join(inkdrop_state.source_display_label(source) for source in order)
    state = "neutral"
    label = "Source order evidence"
    detail = f"Current order: {current_order_label}."
    recommendation_label = ""
    if error:
        state = "watch"
        label = "Source order evidence unavailable"
        detail = f"{detail} {error}"
        recommendation_label = "No automatic change"
    elif active_queued <= 0:
        state = "healthy"
        label = "No queued acquisition backlog"
        detail = f"{detail} The queue has no active rows waiting on automatic search."
        recommendation_label = "No change needed"
    else:
        state = "watch" if problem_health else "healthy"
        if dominant:
            label = f"{dominant['label']} is next for {dominant['count']} queued rows"
        else:
            label = f"{active_queued} queued rows have no clear next source"
        detail = f"{detail} {active_queued} active queued rows are waiting for acquisition."
        if int(row_policy_coverage.get("row_specific_policy_rows") or 0) <= 0:
            detail = f"{detail} All active queued rows are using the current global source order."
        elif int(row_policy_coverage.get("current_global_order_rows") or 0) > 0:
            detail = (
                f"{detail} {int(row_policy_coverage.get('row_specific_policy_rows') or 0)} row"
                f"{'' if int(row_policy_coverage.get('row_specific_policy_rows') or 0) == 1 else 's'} carry a row-specific source order."
            )
        if problem_health:
            detail = f"{detail} {problem_health['label']} is {problem_health['state_label']}."
        if order[:2] == ["local", "slskd"] and problem_health and problem_health.get("provider") == "slskd":
            recommendation_label = "SLSKD First has a warning"
        elif dominant.get("source") == "prowlarr":
            recommendation_label = "Evidence favors Prowlarr First"
        elif dominant.get("source") == "slskd":
            recommendation_label = "Evidence favors SLSKD First"
        else:
            recommendation_label = "Keep current order"

    return {
        "ok": not bool(error),
        "state": state,
        "state_label": state.title(),
        "label": label,
        "detail": detail,
        "recommendation_label": recommendation_label,
        "active_queued": int(active_queued),
        "current_order": order,
        "current_order_labels": [inkdrop_state.source_display_label(source) for source in order],
        "acquisition_order": acquisition_order,
        "acquisition_order_labels": [inkdrop_state.source_display_label(source) for source in acquisition_order],
        "next_acquisition_sources": next_sources,
        "row_policy_coverage": {key: int(value or 0) for key, value in row_policy_coverage.items()},
        "row_policy_chips": row_policy_chips,
        "top_source_orders": top_source_orders,
        "provider_health": health_rows[:6],
        "provider_outcomes": sorted(provider_outcomes.values(), key=lambda item: item.get("provider") or "")[:12],
        "error": error,
    }


def wanted_row_issue_payload(row):
    return {
        "id": row.get("issue_metadata_id") or row.get("issue_id") or f"wanted-{row.get('id')}",
        "kapowarrIssueId": row.get("kapowarr_issue_id"),
        "issueNumber": row.get("issue_number"),
        "title": row.get("issue_title") or "",
        "date": row.get("release_date"),
        "monitored": True,
        "searchQuery": f"{row.get('series') or ''} {row.get('issue_number') or ''}".strip(),
    }


def comicvine_id_from_wanted_row(row):
    if str((row or {}).get("metadata_provider") or "").lower() == "comicvine":
        value = row.get("metadata_id")
        if str(value or "").isdigit():
            return int(value)
    series_id = str((row or {}).get("series_id") or "")
    if series_id.startswith("comicvine:"):
        value = series_id.split(":", 1)[1]
        if value.isdigit():
            return int(value)
    return 0


def comicvine_id_from_series_row(row):
    if str((row or {}).get("metadata_provider") or "").lower() == "comicvine":
        value = row.get("metadata_id")
        if str(value or "").isdigit():
            return int(value)
    series_id = str((row or {}).get("id") or "")
    if series_id.startswith("comicvine:"):
        value = series_id.split(":", 1)[1]
        if value.isdigit():
            return int(value)
    return 0


def comicvine_id_from_queue_row(row):
    if str((row or {}).get("metadata_provider") or "").lower() == "comicvine":
        value = row.get("metadata_id")
        if str(value or "").isdigit():
            return int(value)
    series_id = str((row or {}).get("series_id") or "")
    if series_id.startswith("comicvine:"):
        value = series_id.split(":", 1)[1]
        if value.isdigit():
            return int(value)
    return 0


def queue_identity_from_queue_row(row):
    row = row if isinstance(row, dict) else {}
    cv_id = comicvine_id_from_queue_row(row)
    if cv_id:
        return f"comicvine:{cv_id}"
    native_series_id = review_native_series_id(row)
    if native_series_id:
        return native_identity_key(native_series_id)
    if row.get("kapowarr_id") not in (None, ""):
        return f"kapowarr:{row.get('kapowarr_id')}"
    series_id = str(row.get("series_id") or "").strip()
    if series_id:
        return series_id
    return ""


def export_series_autopilot_queue_from_db(reason="", focus_queue_id=""):
    return inkdrop_state.export_series_autopilot_queue_json(
        STATE_DIR,
        INKDROP_STATE_DB,
        reason=reason or "inkdrop_web_queue_export",
        focus_queue_id=focus_queue_id,
        schema_version=SERIES_AUTOPILOT_QUEUE_SCHEMA_VERSION,
    )


def ensure_autopilot_queue_item_for_retry(row):
    row = row if isinstance(row, dict) else {}
    queue_id = str(row.get("id") or "").strip()
    if not queue_id:
        raise ValueError("queue id is required")
    raw = {}
    try:
        raw = json.loads(row.get("raw_json") or "{}")
    except (TypeError, ValueError):
        raw = {}
    raw = raw if isinstance(raw, dict) else {}
    state = str(row.get("state") or raw.get("state") or "queued").lower()
    previous_state = str(raw.get("retry_previous_state") or state).lower()
    active_transfer = state in {"downloading", "importing"}
    action = "active transfer refreshed" if active_transfer else "retry queued"
    export = export_series_autopilot_queue_from_db(
        reason="inkdrop_core_queue_retry",
        focus_queue_id=queue_id,
    )
    created = False
    if export.get("ok"):
        created = bool(export.get("created"))
    return {
        "action": action,
        "created": created,
        "queue_id": queue_id,
        "previous_state": previous_state,
        "db_authoritative": True,
        "export": export,
    }


def record_inkdrop_action_event(
    event_type,
    entity_type,
    entity_id,
    message,
    raw=None,
    series_id=None,
    issue_id=None,
    created_at=None,
    timeout_seconds=None,
    busy_timeout_ms=None,
):
    try:
        return inkdrop_state.record_history_event(
            INKDROP_STATE_DB,
            event_type=event_type,
            entity_type=entity_type,
            entity_id=entity_id,
            source="inkdrop_web",
            message=message,
            raw=raw or {},
            series_id=series_id,
            issue_id=issue_id,
            created_at=created_at,
            timeout_seconds=timeout_seconds,
            busy_timeout_ms=busy_timeout_ms,
        )
    except Exception as exc:
        return {"ok": False, "error": str(exc)}


def run_inkdrop_queue_retry(payload):
    queue_id = str((payload or {}).get("id") or "").strip()
    row = inkdrop_state.queue_item(INKDROP_STATE_DB, queue_id)
    if not row:
        raise ValueError("queue row not found")
    series = safe_optional_text(row.get("series"), 180)
    if not series:
        raise ValueError("queue row has no series")
    db_retry = inkdrop_state.request_queue_retry(
        INKDROP_STATE_DB,
        queue_id,
        source_order=configured_comicvine_source_order(),
        recovery_steps=list(SERIES_AUTOPILOT_RECOVERY_STEPS),
        source="inkdrop_web",
    )
    if not db_retry.get("ok"):
        raise ValueError(db_retry.get("reason") or db_retry.get("error") or "queue retry failed")
    row = inkdrop_state.queue_item(INKDROP_STATE_DB, queue_id) or row
    update = ensure_autopilot_queue_item_for_retry(row)
    history = db_retry.get("history")
    trigger = launch_series_autopilot(
        {"series": series, "maxIssuesPerSeries": 8},
        reason="inkdrop_queue_retry",
    )
    state = inkdrop_state_public(sync=True, include_history=True, include_views=True)
    watch_log(
        "inkdrop_queue_retry",
        {
            "queueId": queue_id,
            "series": series,
            "issue": row.get("issue_number"),
            "dbRetry": db_retry,
            "update": update,
            "history": history,
            "autopilotTrigger": trigger,
        },
    )
    return {
        "queue": row,
        "series": series,
        "issue": row.get("issue_number"),
        "action": db_retry.get("action") or update.get("action"),
        "dbRetry": db_retry,
        "update": update,
        "history": history,
        "autopilotTrigger": trigger,
        "state": state,
    }


def ensure_series_watch_queued(row):
    data = load_comic_series()
    data.setdefault("watches", [])
    cv_id = comicvine_id_from_series_row(row)
    kapowarr_id = row.get("kapowarr_id")
    series_key = normalize_key(row.get("title"))
    watch = None
    for item in data.get("watches") or []:
        if kapowarr_id not in (None, "") and str(item.get("kapowarrId") or "") == str(kapowarr_id):
            watch = item
            break
        if cv_id and int(item.get("comicvineId") or 0) == cv_id:
            watch = item
            break
        if not watch and series_key and normalize_key(item.get("name")) == series_key:
            watch = item
    created_watch = False
    if watch is None:
        if not cv_id:
            return None, {"created": 0, "resurrected": 0, "updated": 0, "watches": 0, "missingIssues": 0, "reason": "inkdrop_series_search", "skipped": "no_watch_or_comicvine_id"}
        try:
            issues = comicvine_fetch_issues(cv_id)
        except Exception:
            issues = []
        watch = comicvine_native_watch(
            {
                "comicvineId": cv_id,
                "name": row.get("title"),
                "year": row.get("year"),
                "publisher": row.get("publisher"),
                # wanted_count already includes in-progress (actively searching) issues.
                "issueCount": max(int(row.get("wanted_count") or 0), 0),
            },
            auto_grab=bool(row.get("auto_grab", True)),
            issues=issues,
            kapowarr_volume={"id": row.get("kapowarr_id")} if row.get("kapowarr_id") not in (None, "") else None,
        )
        watch, created_watch = upsert_comic_series_watch(data, watch)
    else:
        if watch.get("source") != "kapowarr" and not watch.get("knownIssues") and cv_id:
            try:
                issues = comicvine_fetch_issues(cv_id)
            except Exception:
                issues = []
            if issues:
                watch = comicvine_native_watch(
                    {
                        "comicvineId": cv_id,
                        "name": row.get("title") or watch.get("name"),
                        "year": row.get("year") or watch.get("year"),
                        "publisher": row.get("publisher") or watch.get("publisher"),
                    },
                    auto_grab=watch_auto_grab_enabled(watch),
                    issues=issues,
                    existing=watch,
                    kapowarr_volume={"id": row.get("kapowarr_id")} if row.get("kapowarr_id") not in (None, "") else None,
                )
                upsert_comic_series_watch(data, watch)
        refresh_missing_issues(watch)
    save_comic_series(data)
    queue_update = enqueue_comic_series_watch(watch, reason="inkdrop_series_search")
    queue_update["createdWatch"] = bool(created_watch)
    return watch, queue_update


def update_inkdrop_series_flags(payload):
    payload = payload if isinstance(payload, dict) else {}
    series_id = str(payload.get("id") or payload.get("seriesId") or "").strip()
    if not series_id:
        raise ValueError("series id is required")
    monitored = payload.get("monitored")
    auto_grab = payload.get("autoGrab", payload.get("auto_grab"))
    if monitored is None and auto_grab is None:
        raise ValueError("nothing to update")
    result = inkdrop_state.set_series_flags(
        INKDROP_STATE_DB,
        series_id,
        monitored=bool(monitored) if monitored is not None else None,
        auto_grab=bool(auto_grab) if auto_grab is not None else None,
        source="series_detail_edit",
    )
    if not result.get("ok"):
        raise ValueError(result.get("reason") or "series flag update failed")
    watch_log("inkdrop_series_flags_update", {"seriesId": series_id, **result})
    return result


def run_inkdrop_series_search(payload):
    series_id = str((payload or {}).get("id") or "").strip()
    series_row = inkdrop_state.series_item(INKDROP_STATE_DB, series_id)
    if not series_row:
        raise ValueError("series not found")
    if not series_row.get("monitored"):
        raise ValueError("series is not monitored")
    series = safe_optional_text(series_row.get("title"), 180)
    if not series:
        raise ValueError("series has no title")
    db_queue = inkdrop_state.request_series_search(
        INKDROP_STATE_DB,
        series_id,
        source_order=configured_comicvine_source_order(),
        recovery_steps=list(SERIES_AUTOPILOT_RECOVERY_STEPS),
        source="inkdrop_web",
    )
    if not db_queue.get("ok"):
        raise ValueError(db_queue.get("reason") or db_queue.get("error") or "series search queue failed")
    watch, queue_update = ensure_series_watch_queued(series_row)
    history = db_queue.get("history")
    trigger = launch_series_autopilot(
        {"series": series, "maxIssuesPerSeries": 8},
        reason="inkdrop_series_search",
    )
    state = inkdrop_state_public(sync=True, include_history=True, include_views=True)
    watch_log(
        "inkdrop_series_search",
        {
            "seriesId": series_id,
            "series": series,
            "dbQueue": db_queue,
            "queue": queue_update,
            "history": history,
            "watchId": (watch or {}).get("id") if isinstance(watch, dict) else None,
            "comicvineId": comicvine_id_from_series_row(series_row),
            "kapowarrId": series_row.get("kapowarr_id"),
            "autopilotTrigger": trigger,
        },
    )
    return {
        "series_row": series_row,
        "series": series,
        "watch": public_comic_watch(watch) if isinstance(watch, dict) else None,
        "dbQueue": db_queue,
        "queue": queue_update,
        "history": history,
        "autopilotTrigger": trigger,
        "state": state,
    }


def library_adoption_search_fn(media_type):
    media_type = str(media_type or "comic").strip().lower()
    if media_type == "manga":
        def search(query):
            return mangadex_search_manga(query, limit=5)
        return search

    def search(query):
        return comicvine_search_volumes(query, limit=5)

    return search


def run_library_adoption_plan(payload):
    payload = payload or {}
    root = safe_optional_text(payload.get("root"), 1000)
    if not root:
        raise ValueError("root folder is required")
    media_type = str(payload.get("mediaType") or payload.get("media_type") or "comic").strip().lower()
    if media_type not in ("comic", "manga"):
        raise ValueError("media_type must be comic or manga")
    plan = inkdrop_library_adoption.build_adoption_plan(
        INKDROP_STATE_DB,
        root,
        media_type,
        search_fn=library_adoption_search_fn(media_type),
        max_files=20000,
        max_metadata_lookups=25,
    )
    watch_log(
        "library_adoption_plan",
        {
            "root": root,
            "mediaType": media_type,
            "ok": plan.get("ok"),
            "summary": plan.get("summary"),
            "errors": plan.get("errors"),
        },
    )
    return plan


def run_library_adoption_apply(payload):
    payload = payload or {}
    root = safe_optional_text(payload.get("root"), 1000)
    folder_path = safe_optional_text(payload.get("folderPath") or payload.get("folder_path"), 1000)
    if not root or not folder_path:
        raise ValueError("root and folderPath are required")
    media_type = str(payload.get("mediaType") or payload.get("media_type") or "comic").strip().lower()
    if media_type not in ("comic", "manga"):
        raise ValueError("media_type must be comic or manga")
    series_selection = payload.get("seriesSelection") or payload.get("series_selection")
    if not isinstance(series_selection, dict) or not series_selection:
        raise ValueError("seriesSelection is required")
    confirmed_files = payload.get("confirmedFiles") or payload.get("confirmed_files")
    if not isinstance(confirmed_files, list) or not confirmed_files:
        raise ValueError("confirmedFiles must be a non-empty list")
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    stamp = inkdrop_backup_restore.compact_stamp()
    backup_path = BACKUP_DIR / f"library-adoption-{stamp}-{uuid.uuid4().hex[:12]}.sqlite3"
    result = inkdrop_library_adoption.apply_adoption_folder(
        INKDROP_STATE_DB,
        backup_path,
        root=root,
        folder_path=folder_path,
        media_type=media_type,
        series_selection=series_selection,
        confirmed_files=confirmed_files,
    )
    watch_log(
        "library_adoption_apply",
        {
            "root": root,
            "folderPath": folder_path,
            "mediaType": media_type,
            "registeredCount": len(result.get("registered") or []),
            "skippedCount": len(result.get("skipped") or []),
            "seriesId": result.get("series_id"),
            "backupPath": result.get("backup_path"),
        },
    )
    return result


def _run_archive_conversion_plan_task(task_id):
    def scan_progress(scanned, candidates_found):
        with ARCHIVE_CONVERSION_TASKS_LOCK:
            task = ARCHIVE_CONVERSION_TASKS.get(task_id)
            if not task:
                return
            task["scanned"] = scanned
            task["candidates_found"] = candidates_found

    try:
        plan = inkdrop_archive_conversion.convert_library(dry_run=True, scan_progress=scan_progress)
        with ARCHIVE_CONVERSION_TASKS_LOCK:
            task = ARCHIVE_CONVERSION_TASKS.get(task_id)
            if task:
                task["state"] = "completed"
                task["plan"] = plan
                task["finished_at"] = time.time()
        watch_log(
            "archive_conversion_plan",
            {
                "candidateCount": plan.get("candidate_count"),
                "convertibleCount": plan.get("convertible_count"),
                "needsRarTooling": plan.get("needs_rar_tooling"),
                "blockedOnRarTooling": plan.get("blocked_on_rar_tooling"),
            },
        )
    except Exception as exc:
        with ARCHIVE_CONVERSION_TASKS_LOCK:
            task = ARCHIVE_CONVERSION_TASKS.get(task_id)
            if task:
                task["state"] = "failed"
                task["error"] = inkdrop_manual_search.redacted_text(exc, 240)
                task["finished_at"] = time.time()
        print(f"archive conversion plan task failed task_id={task_id} error={exc}", file=sys.stderr)


def run_archive_conversion_plan_start():
    with ARCHIVE_CONVERSION_TASKS_LOCK:
        for existing_id, existing_task in ARCHIVE_CONVERSION_TASKS.items():
            if existing_task.get("kind") == "plan" and existing_task.get("state") == "running":
                return {"started": False, "already_running": True, "taskId": existing_id}
        task_id = uuid.uuid4().hex
        ARCHIVE_CONVERSION_TASKS[task_id] = {
            "task_id": task_id,
            "kind": "plan",
            "state": "running",
            "started_at": time.time(),
            "finished_at": None,
            "scanned": 0,
            "candidates_found": 0,
            "plan": None,
            "error": None,
        }
    thread = threading.Thread(
        target=_run_archive_conversion_plan_task,
        args=(task_id,),
        name=f"archive-conversion-plan-{task_id[-8:]}",
        daemon=True,
    )
    thread.start()
    return {"started": True, "already_running": False, "taskId": task_id}


def _run_archive_conversion_task(task_id, *, limit, keep_original, include_mislabeled_cbz):
    def progress(result):
        with ARCHIVE_CONVERSION_TASKS_LOCK:
            task = ARCHIVE_CONVERSION_TASKS.get(task_id)
            if not task:
                return
            task["attempted"] += 1
            if result.get("converted"):
                task["converted"] += 1
            elif not result.get("ok"):
                task["failed"] += 1
            task["last_result"] = {"source": result.get("source"), "converted": bool(result.get("converted")), "reason": result.get("reason")}

    try:
        summary = inkdrop_archive_conversion.convert_library(
            dry_run=False,
            limit=limit,
            keep_original=keep_original,
            include_mislabeled_cbz=include_mislabeled_cbz,
            progress=progress,
        )
        with ARCHIVE_CONVERSION_TASKS_LOCK:
            task = ARCHIVE_CONVERSION_TASKS.get(task_id)
            if task:
                task["state"] = "completed" if summary.get("ok") else "failed"
                task["summary"] = summary
                task["finished_at"] = time.time()
        watch_log(
            "archive_conversion_apply",
            {
                "taskId": task_id,
                "converted": summary.get("converted"),
                "failed": summary.get("failed"),
                "skipped": summary.get("skipped"),
                "reason": summary.get("reason"),
            },
        )
    except Exception as exc:
        with ARCHIVE_CONVERSION_TASKS_LOCK:
            task = ARCHIVE_CONVERSION_TASKS.get(task_id)
            if task:
                task["state"] = "failed"
                task["error"] = inkdrop_manual_search.redacted_text(exc, 240)
                task["finished_at"] = time.time()
        print(f"archive conversion task failed task_id={task_id} error={exc}", file=sys.stderr)


def run_archive_conversion_apply_start(payload):
    payload = payload or {}
    with ARCHIVE_CONVERSION_TASKS_LOCK:
        for existing_id, existing_task in ARCHIVE_CONVERSION_TASKS.items():
            if existing_task.get("state") == "running":
                return {"started": False, "already_running": True, "taskId": existing_id}
        task_id = uuid.uuid4().hex
        ARCHIVE_CONVERSION_TASKS[task_id] = {
            "task_id": task_id,
            "state": "running",
            "started_at": time.time(),
            "finished_at": None,
            "attempted": 0,
            "converted": 0,
            "failed": 0,
            "last_result": None,
            "summary": None,
            "error": None,
        }
    limit = payload.get("limit")
    keep_original = not inkdrop_bool_value(payload.get("discardOriginals") or payload.get("discard_originals"), False)
    include_mislabeled_cbz = inkdrop_bool_value(payload.get("includeMislabeledCbz") or payload.get("include_mislabeled_cbz"), False)
    thread = threading.Thread(
        target=_run_archive_conversion_task,
        args=(task_id,),
        kwargs={"limit": limit, "keep_original": keep_original, "include_mislabeled_cbz": include_mislabeled_cbz},
        name=f"archive-conversion-{task_id[-8:]}",
        daemon=True,
    )
    thread.start()
    return {"started": True, "already_running": False, "taskId": task_id}


def archive_conversion_task_status(task_id):
    if not task_id:
        return None
    with ARCHIVE_CONVERSION_TASKS_LOCK:
        task = ARCHIVE_CONVERSION_TASKS.get(task_id)
        return dict(task) if task else None


def inkdrop_series_file_removal_requested(payload):
    payload = payload or {}
    for key in ("deleteFiles", "delete_files", "removeFiles", "remove_files"):
        if key in payload and inkdrop_bool_value(payload.get(key), False):
            return True
    for key in ("keepFiles", "keep_files"):
        if key in payload and not inkdrop_bool_value(payload.get(key), True):
            return True
    return False


def inkdrop_series_file_removal_allowed_roots():
    roots = []
    try:
        paths = inkdrop_runtime_paths()
        roots.extend([paths.get("comic_root"), paths.get("manga_root")])
    except Exception:
        roots.extend([COMIC_ROOT, MANGA_ROOT])
    try:
        settings = inkdrop_state.media_management_settings_context(INKDROP_STATE_DB)
        if isinstance(settings, dict):
            roots.extend([settings.get("comic_root"), settings.get("manga_root")])
    except Exception:
        pass
    out = []
    seen = set()
    for root in roots:
        text = str(root or "").strip()
        if not text:
            continue
        try:
            resolved = str(Path(text).resolve())
        except (OSError, RuntimeError):
            resolved = text
        if resolved in seen:
            continue
        seen.add(resolved)
        out.append(Path(text))
    return out


def inkdrop_series_host_library_path(series_row):
    series_row = series_row if isinstance(series_row, dict) else {}
    candidates = [
        series_row.get("library_path"),
        series_row.get("library_adapter_path"),
    ]
    for candidate in candidates:
        text = str(candidate or "").strip()
        if not text:
            continue
        mapped = None
        try:
            mapped = inkdrop_state.host_path_for_kavita_path(text, db_path=INKDROP_STATE_DB)
        except Exception:
            mapped = None
        if not mapped:
            try:
                mapped = inkdrop_state.host_library_path_from_adapter_path(text)
            except Exception:
                mapped = None
        return str(mapped or text)
    return ""


def inkdrop_series_file_removal_plan(series_row):
    series_row = series_row if isinstance(series_row, dict) else {}
    raw_path = inkdrop_series_host_library_path(series_row)
    if not raw_path:
        return {
            "ok": False,
            "reason": "series_library_path_missing",
            "message": "Series has no managed library path to remove.",
            "series_id": series_row.get("id") or series_row.get("series_id"),
        }
    try:
        candidate = Path(raw_path).expanduser().resolve()
    except (OSError, RuntimeError) as exc:
        return {
            "ok": False,
            "reason": "series_library_path_invalid",
            "message": f"Series library path could not be resolved: {exc}",
            "path": raw_path,
        }
    roots = inkdrop_series_file_removal_allowed_roots()
    matched_root = None
    for root in roots:
        try:
            resolved_root = Path(root).expanduser().resolve()
            candidate.relative_to(resolved_root)
            if candidate == resolved_root:
                continue
            matched_root = resolved_root
            break
        except (OSError, RuntimeError, ValueError):
            continue
    if matched_root is None:
        return {
            "ok": False,
            "reason": "series_library_path_outside_roots",
            "message": "Series library path is outside configured comic/manga roots.",
            "path": str(candidate),
            "allowed_roots": [str(root) for root in roots],
        }
    if not candidate.exists():
        return {
            "ok": True,
            "path": str(candidate),
            "root": str(matched_root),
            "exists": False,
            "skipped": True,
            "reason": "series_library_path_missing_on_disk",
            "message": "Series library path is already absent on disk.",
        }
    if candidate.is_symlink():
        return {
            "ok": False,
            "reason": "series_library_path_is_symlink",
            "message": "Series library path is a symlink and will not be removed by InkDrop.",
            "path": str(candidate),
            "root": str(matched_root),
        }
    if not candidate.is_dir():
        return {
            "ok": False,
            "reason": "series_library_path_not_directory",
            "message": "Series library path is not a directory.",
            "path": str(candidate),
            "root": str(matched_root),
        }
    return {
        "ok": True,
        "path": str(candidate),
        "root": str(matched_root),
        "exists": True,
        "skipped": False,
        "reason": "ready",
    }


def remove_inkdrop_series_library_files(plan):
    plan = plan if isinstance(plan, dict) else {}
    if not plan.get("ok"):
        return {**plan, "deleted": False}
    if plan.get("skipped") or not plan.get("exists"):
        return {**plan, "deleted": False, "skipped": True}
    path = Path(str(plan.get("path") or ""))
    try:
        shutil.rmtree(path)
    except Exception as exc:
        return {
            **plan,
            "ok": False,
            "deleted": False,
            "reason": "series_library_remove_failed",
            "message": f"{type(exc).__name__}: {exc}",
        }
    return {
        **plan,
        "ok": True,
        "deleted": True,
        "skipped": False,
        "reason": "series_library_removed",
        "message": "Series library folder removed from disk.",
    }


def remove_inkdrop_series(payload):
    payload = payload or {}
    series_id = str((payload or {}).get("id") or (payload or {}).get("series_id") or (payload or {}).get("seriesId") or "").strip()
    if not series_id:
        raise ValueError("series id is required")
    series_row = inkdrop_state.series_item(INKDROP_STATE_DB, series_id)
    if not series_row:
        raise ValueError("series not found")
    series = safe_optional_text(series_row.get("title"), 180) or series_id
    remove_files = inkdrop_series_file_removal_requested(payload)
    file_removal = {"requested": False, "deleted": False}
    if remove_files:
        file_removal = inkdrop_series_file_removal_plan(series_row)
        file_removal["requested"] = True
        if not file_removal.get("ok"):
            raise ValueError(file_removal.get("message") or file_removal.get("reason") or "series file removal is not safe")
    result = inkdrop_state.park_series_automation(
        INKDROP_STATE_DB,
        series_id,
        reason="user_removed",
        message="Series removed by user",
        source="inkdrop_web",
        raw={
            "operator_action": "series_remove",
            "series_id": series_id,
            "series": series,
            "metadata_provider": series_row.get("metadata_provider"),
            "metadata_id": series_row.get("metadata_id"),
            "kapowarr_id": series_row.get("kapowarr_id"),
            "keep_files": not remove_files,
            "remove_files": remove_files,
            "library_path": series_row.get("library_path") or series_row.get("library_adapter_path") or series_row.get("library_root"),
            "file_removal": file_removal,
        },
    )
    if not result.get("ok"):
        raise ValueError(result.get("error") or result.get("reason") or "series remove failed")
    if remove_files:
        file_removal = remove_inkdrop_series_library_files(file_removal)
    updated = inkdrop_state.series_item(INKDROP_STATE_DB, series_id)
    watch_log(
        "inkdrop_series_remove",
        {
            "seriesId": series_id,
            "series": series,
            "result": result,
            "filesDeleted": bool(file_removal.get("deleted")),
            "fileRemoval": file_removal,
            "automationOnly": not remove_files,
        },
    )
    return {
        **result,
        "series": result.get("series") or series,
        "series_row": updated,
        "filesDeleted": bool(file_removal.get("deleted")),
        "fileRemoval": file_removal,
        "automationOnly": not remove_files,
    }


def migrate_inkdrop_series_library(payload):
    payload = payload if isinstance(payload, dict) else {}
    series_id = str(payload.get("id") or payload.get("series_id") or payload.get("seriesId") or "").strip()
    destination_root = str(payload.get("destination_root") or payload.get("destinationRoot") or "").strip()
    destination_path = str(payload.get("destination_path") or payload.get("destinationPath") or "").strip() or None
    move_files = inkdrop_bool_value(payload.get("move_files", payload.get("moveFiles")), False)
    result = inkdrop_state.apply_series_library_migration(
        INKDROP_STATE_DB,
        series_id,
        destination_root,
        destination_path=destination_path,
        move_files=move_files,
        source="inkdrop_web",
    )
    if (
        result.get("ok")
        and result.get("rescan_required")
        and str(result.get("destination_media_type") or "").strip().lower() == "manga"
    ):
        try:
            importer = _inkdrop_completed_import_module()
            if hasattr(importer, "apply_path_provider_settings"):
                importer.apply_path_provider_settings()
            result["manga_reader_contract"] = importer.normalize_manga_series_reader_contract(
                result.get("destination_path"),
                result.get("title"),
            )
        except Exception as exc:
            result["manga_reader_contract"] = {
                "ok": False,
                "reason": "manga_reader_contract_failed",
                "error": f"{type(exc).__name__}: {exc}",
            }
        if not result["manga_reader_contract"].get("ok"):
            result["library_frontend_sync"] = {
                "ok": False,
                "skipped": True,
                "reason": "manga_reader_contract_not_ready",
            }
            return result
    if result.get("ok") and result.get("rescan_required"):
        try:
            result["library_frontend_sync"] = run_inkdrop_library_frontend_sync(
                {"series_id": series_id, "force_library_scan": True}
            )
        except Exception as exc:
            result["library_frontend_sync"] = {
                "ok": False,
                "reason": "library_frontend_sync_failed",
                "error": f"{type(exc).__name__}: {exc}",
            }
    return result


def ensure_wanted_watch_queued(row):
    data = load_comic_series()
    data.setdefault("watches", [])
    cv_id = comicvine_id_from_wanted_row(row)
    series_key = normalize_key(row.get("series"))
    watch = None
    for item in data.get("watches") or []:
        if cv_id and int(item.get("comicvineId") or 0) == cv_id:
            watch = item
            break
        if not watch and series_key and normalize_key(item.get("name")) == series_key:
            watch = item
    issue_payload = wanted_row_issue_payload(row)
    created_watch = False
    if watch is None:
        if not cv_id:
            return None, {"created": 0, "resurrected": 0, "updated": 0, "watches": 0, "missingIssues": 0, "reason": "inkdrop_wanted_search", "skipped": "no_watch_or_comicvine_id"}
        try:
            issues = comicvine_fetch_issues(cv_id)
        except Exception:
            issues = [issue_payload]
        watch = comicvine_native_watch(
            {
                "comicvineId": cv_id,
                "name": row.get("series"),
                "year": row.get("year"),
                "publisher": row.get("publisher"),
            },
            auto_grab=True,
            issues=issues or [issue_payload],
        )
        watch, created_watch = upsert_comic_series_watch(data, watch)
    elif watch.get("source") != "kapowarr":
        known = watch.setdefault("knownIssues", {})
        issue_id = str(issue_payload.get("id") or "").strip()
        if issue_id and issue_id not in known:
            known[issue_id] = issue_payload
        refresh_missing_issues(watch)
    else:
        refresh_missing_issues(watch)
    save_comic_series(data)
    queue_update = enqueue_comic_series_watch(watch, reason="inkdrop_wanted_search")
    queue_update["createdWatch"] = bool(created_watch)
    return watch, queue_update


def run_inkdrop_wanted_search(payload):
    wanted_id = str((payload or {}).get("id") or "").strip()
    wanted = inkdrop_state.wanted_item(INKDROP_STATE_DB, wanted_id)
    if not wanted:
        raise ValueError("wanted item not found")
    if str(wanted.get("status") or "").lower() == "satisfied":
        raise ValueError("wanted item is already satisfied")
    series = safe_optional_text(wanted.get("series"), 180)
    if not series:
        raise ValueError("wanted item has no series")
    db_queue = inkdrop_state.request_wanted_search(
        INKDROP_STATE_DB,
        wanted_id,
        source_order=configured_comicvine_source_order(),
        recovery_steps=list(SERIES_AUTOPILOT_RECOVERY_STEPS),
        source="inkdrop_web",
    )
    if not db_queue.get("ok"):
        raise ValueError(db_queue.get("reason") or db_queue.get("error") or "wanted search queue failed")
    watch, queue_update = ensure_wanted_watch_queued(wanted)
    history = db_queue.get("history")
    trigger = launch_series_autopilot(
        {"series": series, "maxIssuesPerSeries": 8},
        reason="inkdrop_wanted_search",
    )
    state = inkdrop_state_public(sync=True, include_history=True, include_views=True)
    watch_log(
        "inkdrop_wanted_search",
        {
            "wantedId": wanted_id,
            "series": series,
            "issue": wanted.get("issue_number"),
            "dbQueue": db_queue,
            "queue": queue_update,
            "history": history,
            "watchId": (watch or {}).get("id") if isinstance(watch, dict) else None,
            "comicvineId": comicvine_id_from_wanted_row(wanted),
            "autopilotTrigger": trigger,
        },
    )
    return {
        "wanted": wanted,
        "series": series,
        "issue": wanted.get("issue_number"),
        "watch": public_comic_watch(watch) if isinstance(watch, dict) else None,
        "dbQueue": db_queue,
        "queue": queue_update,
        "history": history,
        "autopilotTrigger": trigger,
        "state": state,
    }


def allow_inkdrop_blocklist_candidate(payload, *, allowed_by="inkdrop_user"):
    candidate_id = str((payload or {}).get("id") or "").strip()
    result = inkdrop_state.allow_bad_source_candidate(
        INKDROP_STATE_DB,
        candidate_id,
        allowed_by=allowed_by,
    )
    if not result.get("ok"):
        return result
    if result.get("already_allowed"):
        result["retry"] = {"ok": True, "skipped": True, "reason": "already_allowed"}
        return result
    linked = (result.get("candidate") or {}).get("linked_entities") or {}
    retry = {"ok": False, "reason": "no_linked_wanted_work"}
    try:
        if linked.get("queue_id"):
            retry = {"ok": True, "kind": "queue", "result": run_inkdrop_queue_retry({"id": linked["queue_id"]})}
        elif linked.get("wanted_id"):
            retry = {"ok": True, "kind": "wanted", "result": run_inkdrop_wanted_search({"id": linked["wanted_id"]})}
        elif linked.get("series_id"):
            retry = {"ok": True, "kind": "series", "result": run_inkdrop_series_search({"id": linked["series_id"]})}
    except Exception as exc:
        retry = {"ok": False, "reason": "retry_request_failed", "error": str(exc)}
    result["retry"] = retry
    return result


def run_inkdrop_readiness_repair(payload):
    payload = payload if isinstance(payload, dict) else {}
    dry_run = inkdrop_gate_bool(payload, "dryRun", "dry_run")
    apply_requested = inkdrop_gate_bool(payload, "apply", "confirm", "confirmed")
    if not apply_requested:
        dry_run = True
    series_id = str(payload.get("series_id") or payload.get("seriesId") or payload.get("id") or "").strip() or None
    limit = optional_bounded_int(payload.get("limit") or payload.get("maxItems"), 1, 100) or 50
    result = inkdrop_state.apply_readiness_repair(
        INKDROP_STATE_DB,
        state_dir=STATE_DIR,
        dry_run=dry_run,
        series_id=series_id,
        limit=limit,
        source_order=configured_comicvine_source_order(),
        recovery_steps=list(SERIES_AUTOPILOT_RECOVERY_STEPS),
        source="inkdrop_web",
    )
    triggers = []
    if result.get("ok") and not result.get("dry_run"):
        for row in result.get("series") or []:
            series = safe_optional_text((row or {}).get("series"), 180)
            if not series:
                continue
            triggers.append(
                {
                    "series": series,
                    "result": launch_series_autopilot(
                        {"series": series, "maxIssuesPerSeries": 8},
                        reason="readiness_repair",
                    ),
                }
            )
        watch_log(
            "inkdrop_readiness_repair",
            {
                "result": {
                    key: result.get(key)
                    for key in (
                        "ok",
                        "dry_run",
                        "planned_count",
                        "applied_count",
                        "created_wanted",
                        "created_queue",
                        "updated_wanted",
                        "updated_queue",
                        "skipped_count",
                    )
                },
                "series": result.get("series"),
                "queue_ids": result.get("queue_ids"),
                "autopilotTriggers": triggers,
            },
        )
    include_state = inkdrop_bool_value(payload.get("includeState"), False) or inkdrop_bool_value(payload.get("include_state"), False)
    state = inkdrop_state_sections_public() if include_state else None
    out = {
        "repair": result,
        "autopilotTriggers": triggers,
    }
    if state is not None:
        out["state"] = state
    return out


