def provider_field_schema(provider):
    provider_id = str((provider or {}).get("id") or "").strip().lower()
    settings = (provider or {}).get("settings") if isinstance((provider or {}).get("settings"), dict) else {}
    editable = settings.get("editable_fields") if isinstance(settings.get("editable_fields"), list) else []
    secret_fields = set(str(field) for field in (settings.get("secret_fields") if isinstance(settings.get("secret_fields"), list) else []))
    help_by_field = PROVIDER_FIELD_HELP.get(provider_id, {})
    schema = {}
    for field in editable:
        key = str(field)
        if provider_id == "komga" and key == "scan_after_import" and "add_after_import" in {str(item) for item in editable}:
            continue
        meta = dict(COMMON_PROVIDER_FIELD_SCHEMA.get(key, {}))
        meta.setdefault("label", key.replace("_", " ").title())
        if key in secret_fields:
            meta["kind"] = "secret"
            meta["secret"] = True
            meta.setdefault("placeholder", "Saved; leave blank to keep")
        if help_by_field.get(key):
            meta["help"] = help_by_field[key]
        meta["field"] = key
        schema[key] = meta
    return schema


def provider_settings_need_sync(stored_provider, runtime_provider):
    stored_settings = (stored_provider or {}).get("settings") if isinstance((stored_provider or {}).get("settings"), dict) else {}
    runtime_settings = (runtime_provider or {}).get("settings") if isinstance((runtime_provider or {}).get("settings"), dict) else {}
    if not runtime_settings:
        return False
    for key in runtime_settings:
        if key not in stored_settings:
            return True
    for key in ("editable_fields", "secret_fields"):
        stored_values = {str(value) for value in (stored_settings.get(key) if isinstance(stored_settings.get(key), list) else [])}
        for value in runtime_settings.get(key) if isinstance(runtime_settings.get(key), list) else []:
            if str(value) not in stored_values:
                return True
    stored_policy = stored_settings.get("policy") if isinstance(stored_settings.get("policy"), dict) else {}
    runtime_policy = runtime_settings.get("policy") if isinstance(runtime_settings.get("policy"), dict) else {}
    for key in runtime_policy:
        if key not in stored_policy:
            return True
    return False


def app_setting_schema_need_sync(stored_setting, runtime_setting):
    stored_setting = stored_setting if isinstance(stored_setting, dict) else {}
    runtime_setting = runtime_setting if isinstance(runtime_setting, dict) else {}
    for key in ("scope", "label", "description"):
        if str(stored_setting.get(key) or "") != str(runtime_setting.get(key) or ""):
            return True
    return False


def merge_runtime_settings_snapshot(snapshot, runtime):
    snapshot = dict(snapshot or {})
    runtime = runtime if isinstance(runtime, dict) else {}
    runtime_providers = {
        str((provider or {}).get("id") or "").strip().lower(): provider
        for provider in runtime.get("providers") or []
        if isinstance(provider, dict) and str(provider.get("id") or "").strip()
    }
    merged_providers = []
    sync_needed = False
    seen_provider_ids = set()
    for provider in snapshot.get("providers") or []:
        if not isinstance(provider, dict):
            merged_providers.append(provider)
            continue
        provider_id = str(provider.get("id") or "").strip().lower()
        if provider_id:
            seen_provider_ids.add(provider_id)
        runtime_provider = runtime_providers.get(provider_id)
        item = dict(provider)
        if runtime_provider and provider_settings_need_sync(provider, runtime_provider):
            sync_needed = True
            item = dict(provider)
            runtime_settings = (
                runtime_provider.get("settings")
                if isinstance(runtime_provider.get("settings"), dict)
                else {}
            )
            current_settings = item.get("settings") if isinstance(item.get("settings"), dict) else {}
            try:
                item["settings"] = inkdrop_state.merge_provider_settings(
                    json.dumps(current_settings, sort_keys=True),
                    runtime_settings,
                )
            except Exception:
                item["settings"] = current_settings
        merged_providers.append(item)
    missing_runtime_provider_ids = []
    for provider_id, runtime_provider in runtime_providers.items():
        if provider_id in seen_provider_ids:
            continue
        if str(runtime_provider.get("source") or "") != "source_catalog":
            continue
        try:
            item = json.loads(json.dumps(runtime_provider))
        except Exception:
            item = dict(runtime_provider)
        item["settings_runtime_only"] = True
        item["runtime_template"] = True
        item["stored_provider_config"] = False
        item["settings_sync_status"] = "runtime_provider_template_missing"
        merged_providers.append(item)
        missing_runtime_provider_ids.append(provider_id)
    snapshot["providers"] = merged_providers

    runtime_settings = {
        str((setting or {}).get("key") or "").strip().lower(): setting
        for setting in runtime.get("settings") or []
        if isinstance(setting, dict) and str(setting.get("key") or "").strip()
    }
    merged_settings = []
    seen_setting_ids = set()
    for setting in snapshot.get("settings") or []:
        if not isinstance(setting, dict):
            merged_settings.append(setting)
            continue
        setting_id = str(setting.get("key") or "").strip().lower()
        if setting_id:
            seen_setting_ids.add(setting_id)
        runtime_setting = runtime_settings.get(setting_id)
        if runtime_setting and app_setting_schema_need_sync(setting, runtime_setting):
            sync_needed = True
            item = dict(setting)
            for schema_key in ("scope", "label", "description"):
                if runtime_setting.get(schema_key):
                    item[schema_key] = runtime_setting.get(schema_key)
            merged_settings.append(item)
            continue
        merged_settings.append(setting)
    missing_runtime_setting_ids = []
    for setting_id, runtime_setting in runtime_settings.items():
        if setting_id in seen_setting_ids:
            continue
        try:
            item = json.loads(json.dumps(runtime_setting))
        except Exception:
            item = dict(runtime_setting)
        item["settings_runtime_only"] = True
        item["runtime_template"] = True
        item["stored_app_setting"] = False
        item["settings_sync_status"] = "runtime_app_setting_missing"
        merged_settings.append(item)
        missing_runtime_setting_ids.append(setting_id)
    snapshot["settings"] = merged_settings
    snapshot["settings_sync_available"] = True
    snapshot["settings_sync_needed"] = bool(sync_needed or missing_runtime_provider_ids or missing_runtime_setting_ids)
    if sync_needed:
        snapshot["settings_sync_reason"] = "runtime_settings_schema_drift"
    elif missing_runtime_provider_ids:
        snapshot["settings_sync_reason"] = "runtime_provider_template_missing"
    elif missing_runtime_setting_ids:
        snapshot["settings_sync_reason"] = "runtime_app_setting_missing"
    if missing_runtime_provider_ids:
        snapshot["runtime_template_provider_ids"] = missing_runtime_provider_ids
        snapshot["runtime_template_count"] = len(missing_runtime_provider_ids)
    if missing_runtime_setting_ids:
        snapshot["runtime_template_setting_ids"] = missing_runtime_setting_ids
        snapshot["runtime_template_setting_count"] = len(missing_runtime_setting_ids)
    return snapshot


