    slskd_probe_no_candidates = int(slskd_probe_status.get("raw_no_candidate_count") or 0) if isinstance(slskd_probe_status, dict) else 0
    slskd_probe_raw_auto_safe = int(slskd_probe_status.get("raw_auto_grab_safe_count") or slskd_probe_auto_safe or 0) if isinstance(slskd_probe_status, dict) else 0
