def compact_autopilot_summary(summary, limit=12):
    summary = dict(summary) if isinstance(summary, dict) else {}
    rows = summary.get("series") if isinstance(summary.get("series"), list) else []
    preview = rows[:limit]
    summary["series"] = preview
    summary["series_preview_count"] = len(preview)
    summary["series_total_count"] = len(rows)
    return summary, preview


def file_age_minutes(path):
    try:
        return round((time.time() - Path(path).stat().st_mtime) / 60, 1)
    except OSError:
        return None


def python_script_process_status(script_path, ignored_tokens=None):
    ignored_tokens = tuple(ignored_tokens or ())
    try:
        proc = inkdrop_process_lifecycle.run_tracked(
            ["pgrep", "-af", str(Path(script_path).name)],
            check=False,
            capture_output=True,
            text=True,
            timeout=3,
        )
    except Exception:
        return {}
    candidates = []
    for line in (proc.stdout or "").splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split(None, 1)
        if len(parts) < 2:
            continue
        pid, cmd = parts
        if "pgrep -af" in cmd:
            continue
        if any(token in cmd for token in ignored_tokens):
            continue
        if str(script_path) not in cmd and str(Path(script_path).name) not in cmd:
            continue
        rank = 3 if cmd.startswith("/usr/bin/python3 ") or cmd.startswith("python3 ") else 1
        candidates.append((rank, pid, cmd))
    if not candidates:
        return {"running": False}
    _rank, pid, cmd = max(candidates, key=lambda row: row[0])
    try:
        detail = inkdrop_process_lifecycle.run_tracked(
            ["ps", "-o", "pid=", "-o", "ppid=", "-o", "etimes=", "-o", "stat=", "-o", "wchan:32=", "-o", "cmd=", "-p", pid],
            check=False,
            capture_output=True,
            text=True,
            timeout=3,
        )
        row = (detail.stdout or "").strip()
    except Exception:
        row = ""
    status = {"running": True, "pid": int(pid), "cmd": cmd}
    if row:
        parts = row.split(None, 5)
        if len(parts) >= 6:
            status.update({
                "pid": int(parts[0]),
                "ppid": int(parts[1]),
                "elapsed_seconds": int(parts[2]),
                "stat": parts[3],
                "wait_channel": parts[4],
                "cmd": parts[5],
            })
    return status


def process_child_commands(pid, limit=5):
    try:
        pid = int(pid or 0)
    except (TypeError, ValueError):
        return []
    if pid <= 0:
        return []
    try:
        proc = inkdrop_process_lifecycle.run_tracked(
            ["pgrep", "-P", str(pid), "-af"],
            check=False,
            capture_output=True,
            text=True,
            timeout=2,
        )
    except Exception:
        return []
    out = []
    for line in (proc.stdout or "").splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split(None, 1)
        if len(parts) < 2:
            continue
        try:
            child_pid = int(parts[0])
        except ValueError:
            continue
        out.append({"pid": child_pid, "cmd": parts[1]})
        if len(out) >= int(limit or 5):
            break
    return out


def archive_validation_child_detail(process):
    children = process_child_commands((process or {}).get("pid"), limit=6)
    for child in children:
        cmd = str(child.get("cmd") or "")
        if not re.search(r"(?:^|/)(?:7z|7zz|unrar)(?:\s|$)", cmd):
            continue
        path_match = re.search(r"\s(/[^\n]+?\.(?:cbz|cbr|pdf|zip|rar|7z))(?:\s|$)", cmd, re.I)
        archive = Path(path_match.group(1)).name if path_match else ""
        bits = ["validating archive"]
        if archive:
            bits.append(archive)
        wait_channel = str((process or {}).get("wait_channel") or "").strip()
        if wait_channel and wait_channel not in {"-", "do_poll.constprop.0"}:
            bits.append(wait_channel)
        return {
            "detail": " · ".join(bits),
            "child_pid": child.get("pid"),
            "child_cmd": cmd,
            "archive": archive,
        }
    return {}


def series_autopilot_process_status():
    return python_script_process_status(SERIES_AUTOPILOT_SCRIPT, ignored_tokens=("--status-only",))


def slskd_source_probe_process_status():
    return python_script_process_status(SLSKD_SOURCE_PROBE_SCRIPT)


def command_option_value(cmd, option):
    match = re.search(rf"(?:^|\s){re.escape(option)}\s+(.+?)(?=\s+--|$)", str(cmd or ""))
    if not match:
        return ""
    return match.group(1).strip().strip("'\"")


def compact_duration(seconds):
    try:
        seconds = max(0, int(float(seconds or 0)))
    except (TypeError, ValueError):
        seconds = 0
    if seconds <= 0:
        return ""
    if seconds < 90:
        return f"{seconds}s"
    minutes = max(1, round(seconds / 60))
    if minutes < 90:
        return f"{minutes}m"
    hours = max(1, round(minutes / 60))
    return f"{hours}h"


def worker_activity_started_at(process):
    elapsed = int(process.get("elapsed_seconds") or 0) if isinstance(process, dict) else 0
    return time.time() - elapsed if elapsed > 0 else None


def process_activity_elapsed(process):
    try:
        return int(process.get("elapsed_seconds") or 0)
    except (AttributeError, TypeError, ValueError):
        return 0


def process_is_running(process):
    return isinstance(process, dict) and bool(process.get("running"))


def series_autopilot_lock_pressure(process, *, heartbeat_stale=False, child_workers=None):
    child_workers = [str(item).strip() for item in (child_workers or []) if str(item or "").strip()]
    if not process_is_running(process):
        return {
            "active": False,
            "pressure": False,
            "state": "idle",
            "lock_path": str(SERIES_AUTOPILOT_LOCK_PATH),
            "may_delay_queue_writes": False,
        }
    elapsed = process_activity_elapsed(process)
    stat = str(process.get("stat") or "")
    wait_channel = str(process.get("wait_channel") or "").strip()
    kernel_wait = bool(stat.startswith("D"))
    state = "normal"
    pressure = False
    if kernel_wait and elapsed >= SERIES_AUTOPILOT_LOCK_KERNEL_WAIT_SECONDS:
        state = "kernel_wait"
        pressure = True
    elif elapsed >= SERIES_AUTOPILOT_LOCK_PRESSURE_SECONDS:
        state = "write_pressure"
        pressure = True
    elif heartbeat_stale or elapsed >= SERIES_AUTOPILOT_LOCK_NOTICE_SECONDS:
        state = "watch"
        pressure = True

    elapsed_label = compact_duration(elapsed)
    detail = ""
    if state == "kernel_wait":
        detail = f"Series Autopilot has held the scheduler lock for {elapsed_label} and is in kernel wait"
        if wait_channel:
            detail = f"{detail} ({wait_channel})"
    elif state == "write_pressure":
        detail = f"Series Autopilot has held the scheduler lock for {elapsed_label}; queue cleanup writes may wait"
    elif state == "watch":
        if child_workers:
            detail = f"Series Autopilot has held the scheduler lock for {elapsed_label} while waiting on {', '.join(child_workers[:2])}"
        elif heartbeat_stale:
            detail = f"Series Autopilot heartbeat is stale after {elapsed_label}; queue cleanup writes may wait"
        else:
            detail = f"Series Autopilot has held the scheduler lock for {elapsed_label}"
    else:
        detail = f"Series Autopilot lock held {elapsed_label or '0s'}; normal"
    return {
        "active": True,
        "pressure": pressure,
        "state": state,
        "lock_path": str(SERIES_AUTOPILOT_LOCK_PATH),
        "pid": process.get("pid"),
        "elapsed_seconds": elapsed,
        "elapsed_label": elapsed_label,
        "notice_seconds": SERIES_AUTOPILOT_LOCK_NOTICE_SECONDS,
        "pressure_seconds": SERIES_AUTOPILOT_LOCK_PRESSURE_SECONDS,
        "heartbeat_stale": bool(heartbeat_stale),
        "kernel_wait": kernel_wait,
        "wait_channel": wait_channel or None,
        "child_workers": child_workers,
        "may_delay_queue_writes": pressure,
        "detail": detail,
    }


def fast_state_count_snapshot(timeout_seconds=0.25):
    if not INKDROP_STATE_DB.exists():
        return {}
    try:
        timeout = max(0.05, float(timeout_seconds or 0.25))
    except (TypeError, ValueError):
        timeout = 0.25
    snapshot = {"count_snapshot": True}
    try:
        con = sqlite3.connect(f"file:{INKDROP_STATE_DB}?mode=ro", uri=True, timeout=timeout)
        con.row_factory = sqlite3.Row
        try:
            for table, key in (
                ("series", "series"),
                ("issues", "issues"),
                ("wanted_items", "wanted_items"),
                ("queue_items", "queue_items"),
                ("provider_configs", "provider_configs"),
                ("app_settings", "app_settings"),
            ):
                snapshot[key] = int(con.execute(f"select count(*) from {table}").fetchone()[0] or 0)
            snapshot["active_queue_items"] = int(
                con.execute("select count(*) from queue_items where active = 1").fetchone()[0] or 0
            )
            snapshot["wanted_by_status"] = {
                str(row["status"] or "unknown"): int(row["count"] or 0)
                for row in con.execute(
                    """
                    select coalesce(status, 'unknown') status, count(*) count
                    from wanted_items
                    group by coalesce(status, 'unknown')
                    """
                )
            }
            snapshot["queue_by_state"] = {
                str(row["state"] or "unknown"): int(row["count"] or 0)
                for row in con.execute(
                    """
                    select coalesce(state, 'unknown') state, count(*) count
                    from queue_items
                    where active = 1
                    group by coalesce(state, 'unknown')
                    """
                )
            }
        finally:
            con.close()
    except Exception as exc:
        return {
            "count_snapshot": False,
            "count_snapshot_error": f"{type(exc).__name__}: {exc}",
        }
    return snapshot


def bounded_status_state_summary(autopilot_summary=None):
    summary = autopilot_summary if isinstance(autopilot_summary, dict) else {}
    queued = int(summary.get("queued") or 0)
    searching = int(summary.get("searching") or 0)
    downloading = int(summary.get("downloading") or 0)
    importing = int(summary.get("importing") or 0)
    needs_you = int(summary.get("needs_you") or 0)
    source_wait = int(summary.get("source_wait") or 0)
    active = int(summary.get("active") or searching + downloading + importing + source_wait + needs_you)
    count_snapshot = fast_state_count_snapshot()
    import_ledger_cleanup = {}
    try:
        if inkdrop_state is not None and INKDROP_STATE_DB.exists():
            with inkdrop_state.connect_read(INKDROP_STATE_DB, timeout_seconds=1.0, busy_timeout_ms=500) as con:
                import_ledger_cleanup = inkdrop_state.import_ledger_cleanup_rollup(con, limit=1)
    except Exception as exc:
        import_ledger_cleanup = {
            "import_ledger_cleanup_error": f"{type(exc).__name__}: {exc}",
        }
    if count_snapshot.get("active_queue_items"):
        active = max(active, int(count_snapshot.get("active_queue_items") or 0))
    count_snapshot_ok = bool(count_snapshot.get("count_snapshot"))
    payload = {
        "ok": count_snapshot_ok,
        "status_snapshot": True,
        "reason": "bounded_status_snapshot",
        "series_by_ownership": {},
        "wanted_by_status": count_snapshot.get("wanted_by_status") or {},
        "queue_by_state": {
            "queued": queued,
            "searching": searching,
            "downloading": downloading,
            "importing": importing,
            "needs_you": needs_you,
        },
        "queue_by_display_active_state": {
            "queued": queued,
            "searching": searching,
            "downloading": downloading,
            "importing": importing,
            "needs_you": needs_you,
            "source_wait": source_wait,
        },
        "active_queue_items": active,
        "queue_retry_due_items": int(summary.get("retry_due") or 0),
        "queue_retry_later_items": int(summary.get("retry_later") or 0),
        "queue_retry_unscheduled_items": int(summary.get("retry_unscheduled") or 0),
        "queue_backlog_no_candidate_items": int(summary.get("no_candidate") or 0),
        "queue_backlog_source_limited_items": int(summary.get("source_limited") or 0),
        "queue_backlog_language_blocked_items": int(summary.get("language_blocked") or 0),
        "queue_backlog_by_reason": {
            "no_candidate": int(summary.get("no_candidate") or 0),
            "provider_limited": int(summary.get("source_limited") or 0),
            "language_blocked": int(summary.get("language_blocked") or 0),
        },
        **import_ledger_cleanup,
    }
    for key in (
        "series",
        "issues",
        "wanted_items",
        "queue_items",
        "provider_configs",
        "app_settings",
        "count_snapshot",
        "count_snapshot_error",
    ):
        if key in count_snapshot:
            payload[key] = count_snapshot[key]
    if isinstance(count_snapshot.get("queue_by_state"), dict):
        payload["queue_total_by_state"] = count_snapshot["queue_by_state"]
    return payload


def autopilot_source_key(source):
    source = str(source or "").strip().lower()
    aliases = {
        "prowlarr/sab/qb": "prowlarr",
        "prowlarr/sab/qbit": "prowlarr",
        "prowlarr / sab / qb": "prowlarr",
        "soulseek": "slskd",
        "soulseek/slskd": "slskd",
    }
    return aliases.get(source, source)


def normalize_active_task_detail(detail):
    detail = str(detail or "").strip()
    if "budget" not in detail.lower():
        return detail
    parts = [part.strip() for part in detail.split(" · ") if part.strip()]
    has_budget_context = any("budget" in part.lower() and not part.lower().startswith("budget ") for part in parts)
    if not has_budget_context:
        return detail
    parts = [
        part
        for part in parts
        if not (part.lower().startswith("budget ") and "budget" in part.lower())
    ]
    return " · ".join(parts)


def autopilot_active_task_payload(autopilot_status, slskd_process=None):
    if not isinstance(autopilot_status, dict):
        return {}
    active_task = autopilot_status.get("active_task")
    if isinstance(active_task, dict) and active_task:
        payload = dict(active_task)
        payload["detail"] = normalize_active_task_detail(payload.get("detail"))
        return payload
    source = autopilot_source_key(autopilot_status.get("current_source"))
    series = str(autopilot_status.get("current_series") or "").strip()
    note = str(autopilot_status.get("progress_note") or "").strip()
    if not (source or series):
        return {}
    source_label = autopilot_public_source_name(source) or str(autopilot_status.get("current_source") or "").strip()
    budget = None
    if source == "slskd":
        provider = autopilot_status.get("slskd_provider") if isinstance(autopilot_status.get("slskd_provider"), dict) else {}
        budget = provider.get("probe_budget_seconds")
        if isinstance(slskd_process, dict):
            budget = command_option_value(slskd_process.get("cmd"), "--probe-budget-seconds") or budget
    elif source == "prowlarr":
        provider = autopilot_status.get("prowlarr_provider") if isinstance(autopilot_status.get("prowlarr_provider"), dict) else {}
        budget = provider.get("search_budget_seconds")
    budget_label = compact_duration(budget)
    if source == "slskd" and budget_label and "budget" not in note.lower():
        note = f"{note}; SLSKD probe budget {budget_label}" if note else f"SLSKD probe budget {budget_label}"
    elif source == "prowlarr" and budget_label and "budget" not in note.lower():
        note = f"{note}; Prowlarr search budget {budget_label}" if note else f"Prowlarr search budget {budget_label}"
    detail_bits = []
    if series:
        detail_bits.append(series)
    if source_label:
        detail_bits.append(source_label)
    if note:
        detail_bits.append(note)
    if budget_label and "budget" not in note.lower():
        detail_bits.append(f"budget {budget_label}")
    payload = {
        "series": series,
        "source": source,
        "source_label": source_label,
        "note": note,
        "detail": " · ".join(bit for bit in detail_bits if bit),
    }
    try:
        payload["budget_seconds"] = int(float(budget or 0)) or None
    except (TypeError, ValueError):
        payload["budget_seconds"] = None
    return payload


def status_count_bit(status, key, label=None):
    if not isinstance(status, dict):
        return ""
    try:
        count = int(status.get(key) or 0)
    except (TypeError, ValueError):
        count = 0
    if count <= 0:
        return ""
    return f"{count} {label or key.replace('_', ' ')}"


def status_int(status, *keys):
    if not isinstance(status, dict):
        return 0
    values = []
    for key in keys:
        try:
            values.append(int(status.get(key) or 0))
        except (TypeError, ValueError):
            values.append(0)
    return max(values or [0])


def activity_route(section, filter_value="", label=None, provider_filter="", focus=None):
    route = {"section": str(section or "").strip()}
    filter_value = str(filter_value or "").strip()
    label = str(label or "").strip()
    provider_filter = str(provider_filter or "").strip()
    if filter_value:
        route["filter"] = filter_value
    if label:
        route["label"] = label
    if provider_filter:
        route["providerFilter"] = provider_filter
    if isinstance(focus, dict) and focus:
        route["focus"] = focus
    return route


def queue_activity_route(filter_value="work", label=None):
    filter_value = str(filter_value or "work").strip()
    labels = {
        "active": "Queue · Active",
        "work": "Queue · Work",
        "searching": "Queue · Searching",
        "downloading": "Queue · Downloading",
        "importing": "Queue · Importing",
        "provider_wait": "Queue · Waiting",
        "no_candidate": "Queue · No Candidate",
        "exceptions": "Queue · Needs action",
        "waiting": "Queue · Waiting",
    }
    return activity_route("queue", filter_value, label or labels.get(filter_value) or "Queue")


def manual_review_activity_route(filter_value="actionable", label=None):
    filter_value = str(filter_value or "actionable").strip()
    labels = {
        "actionable": "Manual Review · Decisions",
        "ready_import": "Manual Review · Ready Import",
        "source_candidates": "Manual Review · Candidates",
        "source_waiting": "Manual Review · Waiting",
        "source_unchecked": "Manual Review · Search Pending",
        "source_checked": "Manual Review · Checked",
        "source_hints": "Manual Review · Manual Source",
    }
    return activity_route("manual_review", filter_value, label or labels.get(filter_value) or "Manual Review")


def manual_source_server_activity_route(state="source_hints"):
    value = str(state or "source_hints").strip().lower()
    if value == "imported":
        return activity_route("imports", "imported", "Imports · Imported")
    if value == "importing":
        return activity_route("imports", "waiting_scan", "Imports · Library Scan Pending")
    if value in {"ready_import", "staged"}:
        return activity_route("imports", "waiting_scan", "Imports · Ready to Import")
    if value in {"candidate", "candidates"}:
        return manual_review_activity_route("source_candidates")
    if value in {"waiting", "source_waiting"}:
        return manual_review_activity_route("source_waiting")
    if value in {"unchecked", "search_pending"}:
        return manual_review_activity_route("source_unchecked")
    if value == "checked":
        return manual_review_activity_route("source_checked")
    if value in {"attention", "actionable", "needs_you", "blocked", "failed", "error"}:
        return manual_review_activity_route("actionable")
    return manual_review_activity_route("source_hints")


def worker_process_activity_target(activity_id, status=None):
    state = str((status or {}).get("state") or (status or {}).get("status") or "").strip().lower()
    if activity_id in {"rss-discovery-worker", "comicscodes-discovery-worker", "prowlarr-search-worker"}:
        return queue_activity_route("searching")
    if activity_id in {"import-worker", "pack-import-worker"}:
        return queue_activity_route("importing")
    if activity_id == "reconcile-worker":
        if status_int(status, "ready_imports", "ready_import_count", "ready_detected_count") > 0:
            return queue_activity_route("importing")
        if status_int(status, "failed_downloads", "failure_count", "failed_count") > 0 or state in {"failed", "error", "blocked"}:
            return queue_activity_route("exceptions")
        return queue_activity_route("downloading")
    if activity_id == "manual-source-resolver-worker":
        if state in {"failed", "error", "blocked", "needs_you", "attention", "actionable"}:
            return manual_source_server_activity_route("attention")
        if status_int(status, "ready_detected_count", "ready_import_count", "staged_count") > 0 or state in {"ready_import", "staged"}:
            return manual_source_server_activity_route("ready_import")
        if status_int(status, "waiting_count", "waiting") > 0 or state == "waiting":
            return manual_source_server_activity_route("waiting")
        if status_int(status, "eligible_count", "candidate_count", "candidates_found") > 0 or state in {"candidate", "candidates"}:
            return manual_source_server_activity_route("candidates")
        return manual_source_server_activity_route("unchecked")
    return queue_activity_route("work")


def autopilot_server_activity_target(summary, lock_pressure=None):
    summary = summary if isinstance(summary, dict) else {}
    if isinstance(lock_pressure, dict) and lock_pressure.get("pressure"):
        return queue_activity_route("waiting")
    if status_int(summary, "needs_you", "manual_actionable") > 0:
        return manual_review_activity_route("actionable")
    if status_int(summary, "blocked", "failed") > 0:
        return queue_activity_route("exceptions")
    if status_int(summary, "importing", "ready_importing") > 0:
        return queue_activity_route("importing")
    if status_int(summary, "downloading") > 0:
        return queue_activity_route("downloading")
    if status_int(summary, "source_wait", "source_limited") > 0:
        return queue_activity_route("provider_wait")
    if status_int(summary, "no_candidate") > 0:
        return queue_activity_route("no_candidate")
    if status_int(summary, "searching") > 0:
        return queue_activity_route("searching")
    return queue_activity_route("work")


