def _completion_stale_audit_summary():
    now = time.time()
    if now - COMPLETION_STALE_AUDIT_CACHE["ts"] < COMPLETION_STALE_AUDIT_CACHE_TTL_SECONDS:
        cached = COMPLETION_STALE_AUDIT_CACHE.get("data")
        return cached if isinstance(cached, dict) else {}
    with COMPLETION_STALE_AUDIT_CACHE_LOCK:
        if now - COMPLETION_STALE_AUDIT_CACHE["ts"] < COMPLETION_STALE_AUDIT_CACHE_TTL_SECONDS:
            cached = COMPLETION_STALE_AUDIT_CACHE.get("data")
            return cached if isinstance(cached, dict) else {}
        summary = {}
        try:
            module = _inkdrop_completed_import_module()
            result = module.audit_stale_manga_completion(limit=0, include_queue=True)
            if isinstance(result, dict):
                summary = {
                    "ok": bool(result.get("ok")),
                    "stale_total": int(result.get("stale_total") or 0),
                    "stale_needing_attention": int(result.get("stale_needing_attention") or 0),
                    "verified_total": int(result.get("verified_total") or 0),
                    "age_seconds": 0,
                }
                if result.get("ok") is False:
                    summary["error"] = str(result.get("reason") or result.get("error") or "audit failed")
            else:
                summary = {"ok": False, "error": "Unexpected audit result type"}
        except Exception as exc:
            summary = {"ok": False, "error": str(exc), "stale_total": 0, "stale_needing_attention": 0, "verified_total": 0}
        summary["age_seconds"] = int(now - float(COMPLETION_STALE_AUDIT_CACHE["ts"])) if COMPLETION_STALE_AUDIT_CACHE["ts"] else 0
        COMPLETION_STALE_AUDIT_CACHE["ts"] = now
        COMPLETION_STALE_AUDIT_CACHE["data"] = summary
        return summary


def cached_completion_stale_audit_summary():
    now = time.time()
    cached = COMPLETION_STALE_AUDIT_CACHE.get("data")
    if isinstance(cached, dict):
        payload = dict(cached)
        age = max(0, int(now - float(COMPLETION_STALE_AUDIT_CACHE.get("ts") or now)))
        payload["age_seconds"] = int(payload.get("age_seconds") or 0) + age
        payload["cached"] = True
        return payload
    return {
        "ok": False,
        "stale_total": 0,
        "stale_needing_attention": 0,
        "verified_total": 0,
        "age_seconds": 0,
        "cached": False,
        "warming": True,
    }


def pack_duplicate_import_summary(limit=20):
    limit = max(0, min(int(limit or 20), 200))
    summary = {
        "ok": True,
        "audit_command": f"python3 {IMPORT_SCRIPT} --audit-pack-duplicates --audit-limit {limit}",
        "quarantine_command": f"PYTHONDONTWRITEBYTECODE=1 python3 -B {IMPORT_SCRIPT} --quarantine-pack-duplicates --audit-limit {limit}",
        "eligible_count": 0,
        "duplicates": [],
        "mode": "report",
    }
    try:
        module = _inkdrop_completed_import_module()
        result = module.audit_pack_duplicate_imports(limit=limit, quarantine=False, dry_run=True)
        if not isinstance(result, dict):
            summary.update({"ok": False, "error": "Unexpected pack duplicate audit result"})
            return summary
        summary.update(result)
        summary["audit_command"] = f"python3 {IMPORT_SCRIPT} --audit-pack-duplicates --audit-limit {limit}"
        summary["quarantine_command"] = f"PYTHONDONTWRITEBYTECODE=1 python3 -B {IMPORT_SCRIPT} --quarantine-pack-duplicates --audit-limit {limit}"
        summary["eligible_count"] = int(summary.get("eligible_count") or len(summary.get("duplicates") or []))
        summary["duplicates"] = (summary.get("duplicates") or [])[:limit]
        return summary
    except Exception as exc:
        summary.update({"ok": False, "error": f"{type(exc).__name__}: {exc}"})
        return summary


