def command_detail_bits(cmd):
    cmd = str(cmd or "")
    bits = []
    series = command_option_value(cmd, "--series")
    if series:
        bits.append(series)
    kind = command_option_value(cmd, "--kind")
    if kind:
        bits.append(kind)
    review_id = command_option_value(cmd, "--review-id")
    if review_id:
        bits.append(f"review {review_id[:8]}")
    if "--retry-failed" in cmd:
        bits.append("retrying failed downloads")
    if "--manual-inbox" in cmd:
        bits.append("manual inbox")
    if "--suwayomi-staging" in cmd:
        bits.append("Suwayomi staging")
    if "--sync" in cmd and not bits:
        bits.append("sync")
    return bits


def recent_pack_import_log_rows(review_id, max_tail_lines=5000, max_full_bytes=8_000_000):
    review_id = str(review_id or "").strip()
    if not review_id or not PACK_IMPORT_LOG.exists():
        return []
    try:
        size = PACK_IMPORT_LOG.stat().st_size
    except OSError:
        size = 0
    try:
        with PACK_IMPORT_LOG.open("r", encoding="utf-8", errors="replace") as handle:
            source_lines = handle if size <= max_full_bytes else deque(handle, maxlen=max_tail_lines)
            rows = []
            for line in source_lines:
                if review_id not in line:
                    continue
                try:
                    row = json.loads(line)
                except ValueError:
                    continue
                if str(row.get("review_id") or "") == review_id:
                    rows.append(row)
            return rows
    except OSError:
        return []


def compact_seconds_ago(ts):
    try:
        seconds = max(0, int(time.time() - float(ts)))
    except (TypeError, ValueError):
        return ""
    if seconds < 90:
        return f"{seconds}s ago"
    minutes = seconds // 60
    if minutes < 90:
        return f"{minutes}m ago"
    hours = minutes // 60
    if hours < 48:
        return f"{hours}h ago"
    return f"{hours // 24}d ago"


def pack_import_log_progress(review_id):
    rows = recent_pack_import_log_rows(review_id)
    if not rows:
        return {}
    imported = []
    skipped = []
    bad_archives = []
    last_row = None
    for row in rows:
        event = str(row.get("event") or "")
        if event == "pack_import_file":
            imported.append(row)
        elif event.startswith("pack_skip"):
            skipped.append(row)
        if "bad_archive" in event:
            bad_archives.append(row)
        row_ts = float(row.get("ts") or 0)
        last_ts = float((last_row or {}).get("ts") or 0)
        if not last_row or row_ts >= last_ts:
            last_row = row
    last_label = ""
    if isinstance(last_row, dict):
        last_label = str(last_row.get("canonical_filename") or "").strip()
        if not last_label:
            last_path = str(last_row.get("dest") or last_row.get("source") or "").strip()
            if last_path:
                last_label = Path(last_path).name
    return {
        "rows": len(rows),
        "imported_count": len(imported),
        "skipped_count": len(skipped),
        "bad_archive_count": len(bad_archives),
        "last_event": str((last_row or {}).get("event") or ""),
        "last_label": last_label,
        "last_ts": (last_row or {}).get("ts"),
        "last_age": compact_seconds_ago((last_row or {}).get("ts")),
    }


def process_activity(activity_id, label, process, *, status=None, default_detail="Running", count_keys=None, target=None):
    if not process_is_running(process):
        return None
    detail_bits = command_detail_bits(process.get("cmd"))
    child_detail = {}
    if activity_id in {"import-worker", "reconcile-worker"}:
        child_detail = archive_validation_child_detail(process)
        if child_detail.get("detail"):
            detail_bits.insert(0, child_detail["detail"])
    for key, label_text in (count_keys or []):
        bit = status_count_bit(status, key, label_text)
        if bit:
            detail_bits.append(bit)
    state = str((status or {}).get("state") or (status or {}).get("status") or "").strip()
    if state and state.lower() not in {"ok", "running"}:
        detail_bits.append(state)
    return {
        "id": activity_id,
        "label": label,
        "detail": " · ".join(bit for bit in detail_bits if bit) or default_detail,
        "target": target or queue_activity_route("work"),
        "running": True,
        "started_at": worker_activity_started_at(process),
        "elapsed_seconds": process_activity_elapsed(process),
        "pid": process.get("pid"),
        **({"child_pid": child_detail.get("child_pid"), "archive": child_detail.get("archive")} if child_detail else {}),
    }


def pack_import_activity(process, status):
    activity = process_activity(
        "pack-import-worker",
        "Pack Import",
        process,
        status=status,
        default_detail="Importing a local pack",
        count_keys=[("imported_count", "imported"), ("skipped_count", "skipped")],
    )
    if not activity:
        return None
    status = status if isinstance(status, dict) else {}
    cmd = str((process or {}).get("cmd") or "")
    review_id = command_option_value(cmd, "--review-id") or str(status.get("review_id") or "")
    selected_path = command_option_value(cmd, "--path") or str(status.get("selected_path") or "")
    bits = []
    series = str(status.get("series") or "").strip()
    if series:
        bits.append(series)
    if selected_path:
        bits.append(f"local pack {Path(selected_path).name}")
    progress = pack_import_log_progress(review_id)
    max_files = command_option_value(cmd, "--max-files")
    imported_count = max(
        int(status.get("imported_count") or 0),
        int(progress.get("imported_count") or 0),
    )
    skipped_count = max(
        int(status.get("skipped_existing_count") or status.get("skipped_count") or 0),
        int(progress.get("skipped_count") or 0),
    )
    bad_archive_count = max(
        int(status.get("bad_archive_count") or 0),
        int(progress.get("bad_archive_count") or 0),
    )
    if imported_count:
        if max_files:
            bits.append(f"{imported_count}/{max_files} imported")
        else:
            bits.append(f"{imported_count} imported")
    if skipped_count:
        bits.append(f"{skipped_count} skipped")
    if bad_archive_count:
        bits.append(f"{bad_archive_count} bad archives")
    last_label = str(progress.get("last_label") or "").strip()
    last_age = str(progress.get("last_age") or "").strip()
    if last_label:
        last_text = f"last {last_label}"
        if last_age:
            last_text = f"{last_text} {last_age}"
        bits.append(last_text)
    if not imported_count and not skipped_count and not bad_archive_count:
        bits.append("importing")
    if review_id:
        bits.append(f"review {review_id[:8]}")
    activity["detail"] = " · ".join(bits)
    activity["imported_count"] = imported_count
    activity["skipped_count"] = skipped_count
    activity["bad_archive_count"] = bad_archive_count
    activity["last_progress_age"] = last_age
    activity["target"] = queue_activity_route("importing")
    return activity


def recent_finished_pack_activity():
    try:
        state = pack_review_public_state()
    except Exception:
        return None
    finished = state.get("finished") if isinstance(state, dict) else {}
    if not isinstance(finished, dict) or not finished.get("review_id"):
        return None
    evidence = finished.get("finish_evidence") if isinstance(finished.get("finish_evidence"), dict) else {}
    updated_at = (
        pack_status_updated_at(finished)
        or pack_status_updated_at(evidence, PACK_AUTO_IMPORT_STATUS_FILE if evidence else None)
    )
    if updated_at <= 0:
        return None
    age = time.time() - updated_at
    if age < 0 or age > PACK_FINISHED_ACTIVITY_SECONDS:
        return None
    series = safe_optional_text(finished.get("series") or evidence.get("series"), 240)
    title = safe_optional_text(finished.get("title") or evidence.get("title"), 360)
    pack_path = safe_optional_text(finished.get("pack_path") or evidence.get("pack_path"), 800)
    reason = safe_optional_text(finished.get("finish_reason") or evidence.get("pack_review_finish_reason"), 360)
    label = series or title or "Local pack"
    detail_bits = [label]
    if pack_path:
        detail_bits.append(f"local pack {Path(pack_path).name}")
    if reason:
        detail_bits.append(reason)
    detail_bits.append(f"finished {compact_seconds_ago(updated_at)}")
    activity = {
        "id": f"pack-finished-{safe_optional_text(finished.get('review_id'), 48)}",
        "label": "Pack Finished",
        "detail": " · ".join(bit for bit in detail_bits if bit),
        "target": {"section": "history", "filter": "imports", "label": "Open History: Imports"},
        "running": False,
        "state": "finished",
        "started_at": updated_at,
        "review_id": finished.get("review_id"),
        "series": series,
        "title": title,
    }
    series_id = pack_history_series_id(finished, evidence)
    if series_id:
        activity["series_id"] = series_id
    return activity


