                    provider_filter=(query.get("provider_filter") or query.get("providerFilter") or [None])[0],
                    queue_filter=(query.get("queue_filter") or query.get("queueFilter") or [None])[0],
                    wanted_filter=(query.get("wanted_filter") or query.get("wantedFilter") or [None])[0],
                    series_filter=(query.get("series_filter") or query.get("seriesFilter") or [None])[0],
                    issue_filter=(query.get("issue_filter") or query.get("issueFilter") or [None])[0],
                    history_filter=(query.get("history_filter") or query.get("historyFilter") or [None])[0],
                    import_filter=(query.get("import_filter") or query.get("importFilter") or [None])[0],
                    download_filter=(query.get("download_filter") or query.get("downloadFilter") or [None])[0],
